export const TRACKS = [
{ id:'prealgebra', n:'Pre-algebra', sub:'Number sense and the rules everything else rests on', lessons:[
  { id:'signed', title:'Signed numbers', demo:'numberLine', cs:'Computers store negative integers in two\u2019s complement, which is why the byte 0xFF can mean 255 or \u22121 depending on how you read it. Every off-by-one with unsigned subtraction traces back to not being fluent with signs.', idea:'A minus sign is a direction, not a different species of number.',
    f:[['Subtraction is addition','a \u2212 b = a + (\u2212b)','There is only one operation.'],['Sign product','(\u2212a)(\u2212b) = ab','Two flips return you to the start.'],['Absolute value','|a| = a if a \u2265 0, else \u2212a','Distance from zero, never negative.']],
    q:[{t:'mc',q:'Evaluate \u22127 \u2212 (\u22123).',o:['\u221210','\u22124','4','10'],a:1,e:'Subtracting a negative adds: \u22127 + 3 = \u22124. The two minus signs cancel into a plus, then you move three units right from \u22127.'},
       {t:'in',q:'Evaluate |\u221212| + (\u22125).',a:'7',alt:['+7'],s:['|\u221212| = 12 \u2014 absolute value strips the sign.','12 + (\u22125) = 12 \u2212 5.','= 7'],e:'Take the absolute value first, then add the signed number.'}]},
  { id:'order-ops', title:'Order of operations', cs:'Operator precedence in every programming language is the same idea with more operators. Knowing that a + b * c binds the multiply first is why you can read someone else\u2019s expression without running it.', idea:'Precedence is a ranking that tells you which operation is impatient.',
    f:[['Precedence order','() \u2192 exponents \u2192 \u00d7 \u00f7 \u2192 + \u2212','Left to right within a tier.'],['Distribution','a(b + c) = ab + ac','How to remove a bracket legally.'],['Negation binds loose','\u2212x\u00b2 = \u2212(x\u00b2)','Not (\u2212x)\u00b2. This one bites.']],
    q:[{t:'mc',q:'Evaluate 6 + 2 \u00d7 3\u00b2.',o:['24','72','144','30'],a:0,e:'Exponent first: 3\u00b2 = 9. Then multiply: 2 \u00d7 9 = 18. Then add: 6 + 18 = 24. Adding before multiplying would give 72, which is the classic mistake.'},
       {t:'in',q:'Evaluate (4 + 2)\u00b2 \u2212 10 \u00f7 5.',a:'34',s:['Brackets first: 4 + 2 = 6.','Exponent: 6\u00b2 = 36.','Division before subtraction: 10 \u00f7 5 = 2.','36 \u2212 2 = 34'],e:'The bracket outranks the exponent, and the division outranks the subtraction.'}]},
  { id:'fractions', title:'Fractions and ratios', cs:'Rational arithmetic is what you reach for when floating point lies to you \u2014 0.1 + 0.2 \u2260 0.3 in binary, but 1/10 + 2/10 is exact. Aspect ratios, sampling rates and gear ratios are all fractions wearing different hats.', idea:'A fraction is a division you have not finished yet.',
    f:[['Addition','a/b + c/d = (ad + bc)/bd','Common denominator, then add tops.'],['Multiplication','(a/b)(c/d) = ac/bd','Straight across.'],['Division','(a/b) \u00f7 (c/d) = ad/bc','Flip the second, then multiply.']],
    q:[{t:'mc',q:'Simplify (2/3) \u00f7 (4/9).',o:['8/27','3/2','2/3','9/8'],a:1,e:'Flip and multiply: (2/3) \u00d7 (9/4) = 18/12 = 3/2. Dividing by a fraction smaller than one makes the result bigger.'},
       {t:'in',q:'Write 3/4 + 5/6 as a single fraction in lowest terms.',a:'19/12',s:['Common denominator of 4 and 6 is 12.','3/4 = 9/12 and 5/6 = 10/12.','9/12 + 10/12 = 19/12.','19 and 12 share no factor, so it is already reduced.'],e:'Least common denominator keeps the numbers small; any common denominator works.'}]},
  { id:'exponents', title:'Exponents and roots', graph:'powers', cs:'Powers of two are the native vocabulary of memory: 2\u00b9\u2070 = 1024 is a kibibyte, and x << 3 is x \u00d7 2\u00b3. Every capacity, address space and hash table size you will meet is a power of two.', idea:'An exponent counts how many copies of the base are multiplied together.',
    f:[['Product','a\u1d50 \u00b7 a\u207f = a\u1d50\u207a\u207f','Multiply, exponents add.'],['Power of a power','(a\u1d50)\u207f = a\u1d50\u207f','Exponents multiply.'],['Negative exponent','a\u207b\u207f = 1 / a\u207f','A reciprocal, not a negative number.'],['Fractional exponent','a^(1/n) = \u207f\u221aa','Roots are exponents in disguise.']],
    q:[{t:'mc',q:'2\u2078 \u00b7 2\u2075 equals which of these?',o:['2\u2074\u2070','4\u00b9\u00b3','2\u00b9\u00b3','2\u00b3'],a:2,e:'Same base, so exponents add: 2\u2078\u207a\u2075 = 2\u00b9\u00b3 = 8192. Multiplying the bases as well would give 4\u00b9\u00b3, which is far too large.'},
       {t:'in',q:'How many bits are needed to address 1024 distinct memory slots?',a:'10',s:['Addressing n slots needs an exponent b with 2\u1d47 \u2265 n.','1024 = 2\u00b9\u2070.','So b = 10 bits.'],e:'This is a logarithm in disguise: log\u2082(1024) = 10.'}]},
  { id:'factors', title:'Factors, multiples and divisibility', cs:'Divisibility decides whether a buffer divides evenly into blocks, whether a loop unrolls cleanly, and whether an index wraps without a remainder. The divisibility tests are the same reasoning as a mod check.', idea:'One number divides another when the division leaves no remainder.',
    f:[['Divisibility by 2','Last digit is even','Or the low bit is 0.'],['Divisibility by 3','Digit sum divisible by 3','Works for 9 too.'],['Divisibility by 5','Last digit is 0 or 5','Base-10 artefact.'],['Prime factorisation','Every integer factors uniquely','The atoms of arithmetic.']],
    q:[{t:'mc',q:'Which number is divisible by 3?',o:['124','238','471','505'],a:2,e:'Add the digits: 4 + 7 + 1 = 12, and 12 is divisible by 3, so 471 is. The others give digit sums 7, 13 and 10, none of which are multiples of 3.'},
       {t:'in',q:'What is the greatest common factor of 24 and 36?',a:'12',s:['Factors of 24: 1, 2, 3, 4, 6, 8, 12, 24.','Factors of 36: 1, 2, 3, 4, 6, 9, 12, 18, 36.','The largest shared factor is 12.'],e:'Euclid\u2019s algorithm gets the same answer without listing anything.'}]},
  { id:'decimals', title:'Decimals, percents and rounding', cs:'Percentages are how every benchmark, error rate and cache hit ratio is reported. Rounding is where floating point stops matching arithmetic, which is why 0.1 + 0.2 does not equal 0.3 in any language you will use.', idea:'A percent is a fraction with a fixed denominator of 100.',
    f:[['Percent to decimal','Divide by 100','35% = 0.35.'],['Percent of a number','part = percent \u00d7 whole','0.2 \u00d7 80 = 16.'],['Percent change','(new \u2212 old) / old \u00d7 100','Sign gives direction.'],['Rounding','Look at the next digit','5 or more rounds up.']],
    q:[{t:'mc',q:'A benchmark drops from 200ms to 150ms. What is the percent improvement?',o:['25%','33%','50%','75%'],a:0,e:'Change is (150 \u2212 200)/200 = \u22120.25, a 25% decrease. Dividing by the new value instead gives 33%, which is the most common way this number gets misreported.'},
       {t:'in',q:'What is 15% of 240?',a:'36',s:['Convert: 15% = 0.15.','0.15 \u00d7 240.','= 36'],e:'Ten percent is 24, and half of that is 12, so 36 \u2014 a fast mental check.'}]},
  { id:'ratios', title:'Ratios, proportions and rates', graph:'rate', cs:'Aspect ratios, compression ratios, throughput per second and load per server are all rates. Scaling a system correctly is solving a proportion.', idea:'A proportion says two ratios are equal, which lets you solve for the missing fourth value.',
    f:[['Ratio','a : b or a/b','A comparison, not a count.'],['Proportion','a/b = c/d','Cross-multiply: ad = bc.'],['Unit rate','quantity per one unit','Divide to normalise.'],['Scaling','Multiply both parts','Ratio is preserved.']],
    q:[{t:'mc',q:'A server handles 300 requests in 12 seconds. What is the unit rate?',o:['12 req/s','25 req/s','36 req/s','300 req/s'],a:1,e:'Divide to normalise to one second: 300 / 12 = 25 requests per second. Unit rates make two systems directly comparable.'},
       {t:'in',q:'If 3 servers handle 900 users, how many users do 5 servers handle at the same rate?',a:'1500',s:['Rate per server: 900 / 3 = 300 users.','Five servers at that rate: 5 \u00d7 300.','= 1500'],e:'Or cross-multiply 3/900 = 5/x directly.'}]},
  { id:'expressions', title:'Variables and expressions', cs:'An expression is code before it runs. Combining like terms is the same operation a compiler performs during constant folding, and substituting a value is exactly what a function call does.', idea:'A variable is a named placeholder, and simplifying means writing the same value with fewer symbols.',
    f:[['Like terms','Same variable, same power','3x + 5x = 8x.'],['Distribution','a(b + c) = ab + ac','Removing a bracket.'],['Substitution','Replace the letter with a value','Then evaluate normally.'],['Coefficient','The number multiplying a variable','In 7x it is 7.']],
    q:[{t:'mc',q:'Simplify 4x + 3 + 2x \u2212 7.',o:['6x \u2212 4','8x \u2212 4','6x + 10','2x \u2212 4'],a:0,e:'Combine the x terms: 4x + 2x = 6x. Combine the constants: 3 \u2212 7 = \u22124. You cannot merge 6x with \u22124 because they are not like terms.'},
       {t:'in',q:'Evaluate 3x\u00b2 \u2212 2x when x = 4.',a:'40',s:['Substitute first: 3(4)\u00b2 \u2212 2(4).','Exponent before multiplication: 3(16) \u2212 8.','48 \u2212 8 = 40'],e:'Order of operations applies after substitution, not before.'}]},
  { id:'inequalities', title:'Inequalities', demo:'inequality', cs:'Every loop bound, array bounds check and guard clause is an inequality. The rule that multiplying by a negative flips the sign is behind a whole class of off-by-one and reversed-comparison bugs.', idea:'An inequality describes a range of valid values rather than a single one.',
    f:[['Same-side rules','Add or subtract freely','Direction unchanged.'],['Negative multiply','Multiplying by \u22121 flips the sign','< becomes >.'],['Compound','a < x < b','Two constraints at once.'],['Interval notation','[a, b] closed, (a, b) open','Bracket includes, paren excludes.']],
    q:[{t:'mc',q:'Solve \u22122x > 6.',o:['x > 3','x < 3','x > \u22123','x < \u22123'],a:3,e:'Divide both sides by \u22122, which flips the inequality: x < \u22123. Forgetting the flip gives x > \u22123 and reverses the entire answer set.'},
       {t:'in',q:'How many integers satisfy 2 \u2264 x < 9?',a:'7',s:['The values are 2, 3, 4, 5, 6, 7, 8.','9 is excluded because the inequality is strict on that side.','That is 7 integers.'],e:'This is exactly a half-open loop range, the same convention as for i in range(2, 9).'}]},
  { id:'coordinates', title:'The coordinate plane', cs:'Screen coordinates, plot axes and grid-based collision detection all live on this plane, though screens usually flip the y-axis so it grows downward. Distance between points is Pythagoras.', idea:'An ordered pair locates a point by how far across and how far up it sits.',
    f:[['Point','(x, y)','Across first, then up.'],['Quadrants','I (+,+), II (\u2212,+), III (\u2212,\u2212), IV (+,\u2212)','Counterclockwise from top right.'],['Distance','\u221a((x\u2082\u2212x\u2081)\u00b2 + (y\u2082\u2212y\u2081)\u00b2)','Pythagoras.'],['Midpoint','((x\u2081+x\u2082)/2, (y\u2081+y\u2082)/2)','Average both coordinates.']],
    q:[{t:'mc',q:'Which quadrant contains (\u22123, 5)?',o:['I','II','III','IV'],a:1,e:'Negative x and positive y puts it up and to the left, which is quadrant II. Quadrants number counterclockwise starting from the top right.'},
       {t:'in',q:'What is the distance between (0, 0) and (6, 8)?',a:'10',s:['Distance = \u221a((6\u22120)\u00b2 + (8\u22120)\u00b2).','= \u221a(36 + 64) = \u221a100.','= 10'],e:'The 3-4-5 triangle scaled by two \u2014 worth recognising instantly.'}]},
  { id:'word-problems', title:'Turning words into equations', cs:'Every requirement document is a word problem. Translating "the cache should hold twice as many entries as connections, plus a reserve of 50" into 2c + 50 is the same skill as writing the equation.', idea:'Name the unknown, write what the sentence says about it, then solve.',
    f:[['Name it','Let x be the unknown','Always write this down.'],['Translate','"of" \u2192 \u00d7, "is" \u2192 =','Word to symbol.'],['More / less than','x + 5 / x \u2212 5','Watch the order on "less than".'],['Check','Substitute back into the words','Not into your equation.']],
    q:[{t:'mc',q:'"Seven less than twice a number is 15." Which equation is right?',o:['7 \u2212 2x = 15','2x \u2212 7 = 15','2(x \u2212 7) = 15','7 \u2212 2 + x = 15'],a:1,e:'"Twice a number" is 2x, and "seven less than" subtracts from it: 2x \u2212 7. The phrase reverses the written order, which is why option one is the standard trap.'},
       {t:'in',q:'A server costs $40 plus $3 per user. How many users make the total $130?',a:'30',s:['Let u be users: 40 + 3u = 130.','Subtract 40: 3u = 90.','Divide by 3: u = 30'],e:'Fixed cost plus variable rate is y = mx + b with different words.'}]},
]},

{ id:'algebra', n:'Algebra I & II', sub:'Manipulating unknowns without breaking them', lessons:[
  { id:'linear', title:'Linear equations', graph:'line', cs:'Solving for a variable is what you do every time you invert a formula \u2014 converting a buffer size to an element count, or a frame index to a timestamp. The same balance rules make refactoring arithmetic in code safe.', idea:'Whatever you do to one side, do to the other, and the equality survives.',
    f:[['Slope-intercept','y = mx + b','m is rate of change, b is the start.'],['Slope from two points','m = (y\u2082 \u2212 y\u2081)/(x\u2082 \u2212 x\u2081)','Rise over run.'],['Point-slope','y \u2212 y\u2081 = m(x \u2212 x\u2081)','Build a line from one point and a rate.']],
    q:[{t:'mc',q:'Solve 5x \u2212 8 = 2x + 7.',o:['x = 1','x = 3','x = 5','x = 15'],a:2,e:'Subtract 2x from both sides: 3x \u2212 8 = 7. Add 8: 3x = 15. Divide by 3: x = 5.'},
       {t:'in',q:'A line passes through (2, 3) and (6, 11). What is its slope?',a:'2',s:['m = (y\u2082 \u2212 y\u2081)/(x\u2082 \u2212 x\u2081).','= (11 \u2212 3)/(6 \u2212 2)','= 8/4 = 2'],e:'Slope is a rate: the output climbs two units for every one unit of input.'}]},
  { id:'quadratics', title:'Quadratics', graph:'parabola', cs:'A quadratic is the shape of every nested-loop cost curve: n(n\u22121)/2 comparisons in bubble sort is a parabola. Physics in a game engine \u2014 projectile arcs, collision times \u2014 is solving quadratics sixty times a second.', idea:'A quadratic bends once, so it crosses zero at most twice.',
    f:[['Quadratic formula','x = (\u2212b \u00b1 \u221a(b\u00b2 \u2212 4ac)) / 2a','Solves ax\u00b2 + bx + c = 0 always.'],['Discriminant','\u0394 = b\u00b2 \u2212 4ac','\u0394 > 0 two roots, = 0 one, < 0 none real.'],['Vertex','x = \u2212b / 2a','Where the curve turns.']],
    q:[{t:'mc',q:'How many real roots does x\u00b2 + 2x + 5 = 0 have?',o:['Two','One','None','Infinitely many'],a:2,e:'The discriminant is 2\u00b2 \u2212 4(1)(5) = 4 \u2212 20 = \u221216. A negative discriminant means the parabola never touches the x-axis, so there are no real roots.'},
       {t:'in',q:'Solve x\u00b2 \u2212 7x + 12 = 0. Give the larger root.',a:'4',s:['Look for two numbers that multiply to 12 and add to \u22127: \u22123 and \u22124.','So x\u00b2 \u2212 7x + 12 = (x \u2212 3)(x \u2212 4).','A product is zero when a factor is zero: x = 3 or x = 4.','The larger root is 4.'],e:'Factoring is faster than the formula when the numbers are friendly.'}]},
  { id:'systems', title:'Systems of equations', cs:'Solving several equations at once is the core of linear solvers, constraint layout engines and 3D transforms. Auto-layout in a UI framework is a system of equations being solved on every resize.', idea:'Each equation is a constraint; the solution is the point that satisfies all of them.',
    f:[['Elimination','Scale a row, then add or subtract','Kill one variable at a time.'],['Substitution','Solve for one variable, insert it','Best when a coefficient is 1.'],['2\u00d72 determinant','ad \u2212 bc','Zero means no unique solution.']],
    q:[{t:'mc',q:'Solve x + y = 10 and x \u2212 y = 4.',o:['x = 7, y = 3','x = 3, y = 7','x = 6, y = 4','x = 5, y = 5'],a:0,e:'Add the two equations: 2x = 14, so x = 7. Substitute back: 7 + y = 10, so y = 3.'},
       {t:'in',q:'For 2x + 3y = 12 and 4x + 6y = 24, how many solutions are there? Answer with a number or the word "infinite".',a:'infinite',alt:['infinitely many','infinite solutions'],s:['The second equation is exactly twice the first.','Both describe the same line.','Every point on that line satisfies both, so there are infinitely many solutions.'],e:'The determinant is 2\u00b76 \u2212 3\u00b74 = 0, which flags a non-unique system.'}]},
  { id:'functions', title:'Functions and inverses', cs:'A hash function is deliberately hard to invert; an encoding function must be perfectly invertible. Knowing whether a mapping has an inverse is the difference between compression and destruction.', idea:'A function has an inverse only when no two inputs share an output.',
    f:[['Composition','(f \u2218 g)(x) = f(g(x))','Apply g first.'],['Inverse property','f(f\u207b\u00b9(x)) = x','Undo, exactly.'],['Domain rule','Inverse swaps domain and range','Outputs become inputs.']],
    q:[{t:'mc',q:'Which function has no inverse over all real numbers?',o:['f(x) = 2x + 1','f(x) = x\u00b3','f(x) = x\u00b2','f(x) = x \u2212 5'],a:2,e:'x\u00b2 sends both 3 and \u22123 to 9, so it is not one-to-one and cannot be undone without extra information. Restricting it to x \u2265 0 would make it invertible.'},
       {t:'in',q:'If f(x) = 3x \u2212 6, what is f\u207b\u00b9(9)?',a:'5',s:['Set 3x \u2212 6 = 9 \u2014 the inverse asks which input produced 9.','3x = 15','x = 5'],e:'Finding an inverse value is just solving the original equation backwards.'}]},
  { id:'polynomials', title:'Polynomials and factoring', cs:'Polynomial evaluation is what Horner\u2019s method optimises, CRC checksums are polynomial division over bits, and factoring is how a computer algebra system simplifies anything at all.', idea:'A polynomial is a sum of powers, and factoring rewrites it as a product so its roots become visible.',
    f:[['Degree','Highest power of x','Controls end behaviour and root count.'],['Difference of squares','a\u00b2 \u2212 b\u00b2 = (a\u2212b)(a+b)','The most-used factoring pattern.'],['Zero product','ab = 0 \u21d2 a = 0 or b = 0','Why factored form solves equations.'],['Horner form','ax\u00b3+bx\u00b2+cx+d = ((ax+b)x+c)x+d','Evaluate with n multiplies, not n\u00b2.']],
    q:[{t:'mc',q:'Factor x\u00b2 \u2212 49.',o:['(x \u2212 7)\u00b2','(x \u2212 7)(x + 7)','(x \u2212 49)(x + 1)','It does not factor'],a:1,e:'Difference of squares: x\u00b2 \u2212 49 = x\u00b2 \u2212 7\u00b2 = (x \u2212 7)(x + 7). The pattern only works with a minus sign; x\u00b2 + 49 has no real factorisation.'},
       {t:'in',q:'How many multiplications does Horner\u2019s method use for a degree-5 polynomial?',a:'5',s:['Horner nests the polynomial: (((((a\u2085x+a\u2084)x+a\u2083)x+a\u2082)x+a\u2081)x+a\u2080.','One multiplication per nesting level.','Degree 5 \u21d2 5 multiplications, versus 15 the naive way.'],e:'This is the standard way compilers and calculators evaluate polynomials.'}]},
  { id:'rational', title:'Rational expressions and asymptotes', cs:'Rates like throughput = work/time are rational expressions, and their asymptotes are the saturation limits every performance curve shows. Division by zero here is the same crash as in your code.', idea:'A rational expression is a ratio of polynomials, undefined exactly where the bottom is zero.',
    f:[['Domain','Denominator \u2260 0','Excluded values are the poles.'],['Simplify','Factor, then cancel common factors','Only factors cancel, never terms.'],['Vertical asymptote','Zero of denominator (after cancelling)','The graph blows up.'],['Horizontal asymptote','Compare leading degrees','Top < bottom \u21d2 y = 0; equal \u21d2 ratio of leads.']],
    q:[{t:'mc',q:'What is the horizontal asymptote of y = (3x\u00b2 + 1)/(x\u00b2 + 5)?',o:['y = 0','y = 3','y = 5','There is none'],a:1,e:'Degrees match, so the asymptote is the ratio of leading coefficients: 3/1 = 3. This is the limit-at-infinity argument from the calculus track, and the Big-O argument in disguise.'},
       {t:'in',q:'For f(x) = (x + 2)/(x \u2212 5), which x makes f undefined?',a:'5',s:['A fraction is undefined where its denominator is zero.','x \u2212 5 = 0.','x = 5'],e:'Every division in code needs the same one-line check.'}]},
]},

{ id:'trig', n:'Trigonometry', sub:'Angles, rotation and periodic behaviour', lessons:[
  { id:'right-triangles', title:'Right triangles and SOH-CAH-TOA', cs:'Any 2D vector turns into an angle and a length with these three ratios, which is how a sprite faces its target or a joystick reading becomes a heading.', idea:'In a right triangle, the angle fixes the ratio of the sides, regardless of size.',
    f:[['Sine','sin \u03b8 = opposite / hypotenuse','Vertical component.'],['Cosine','cos \u03b8 = adjacent / hypotenuse','Horizontal component.'],['Tangent','tan \u03b8 = opposite / adjacent','Slope of the ray.'],['Pythagoras','a\u00b2 + b\u00b2 = c\u00b2','Length from components.']],
    q:[{t:'mc',q:'A right triangle has legs 3 and 4. What is the hypotenuse?',o:['5','7','\u221a7','12'],a:0,e:'3\u00b2 + 4\u00b2 = 9 + 16 = 25, and \u221a25 = 5. This is the smallest whole-number right triangle.'},
       {t:'in',q:'A vector has components x = 6 and y = 8. What is its length?',a:'10',s:['Length = \u221a(x\u00b2 + y\u00b2).','= \u221a(36 + 64)','= \u221a100 = 10'],e:'Vector magnitude is Pythagoras with the components as legs.'}]},
  { id:'unit-circle', title:'The unit circle and radians', cs:'Math.sin in every standard library takes radians, not degrees. Passing degrees is one of the most common silent bugs in graphics code.', idea:'A radian is the angle whose arc length equals the radius, so a full turn is 2\u03c0 of them.',
    f:[['Conversion','radians = degrees \u00d7 \u03c0/180','180\u00b0 = \u03c0.'],['Circle point','(cos \u03b8, sin \u03b8)','Coordinates on the unit circle.'],['Arc length','s = r\u03b8','\u03b8 in radians.']],
    q:[{t:'mc',q:'What is 90\u00b0 in radians?',o:['\u03c0','\u03c0/2','\u03c0/4','2\u03c0'],a:1,e:'A full turn is 2\u03c0 and 90\u00b0 is a quarter turn, so it is 2\u03c0/4 = \u03c0/2 \u2248 1.5708.'},
       {t:'in',q:'What is cos(\u03c0)?',a:'-1',alt:['\u22121'],s:['\u03c0 radians is half a turn, pointing along the negative x-axis.','The point on the unit circle there is (\u22121, 0).','cos is the x-coordinate, so cos(\u03c0) = \u22121.'],e:'Reading cos and sin as the x and y of a point removes most memorisation.'}]},
  { id:'identities', title:'Trig identities', cs:'The angle-addition identities are exactly the entries of a 2D rotation matrix, which is why composing two rotations adds their angles.', idea:'Identities are the algebra that lets you rewrite one trig expression as another.',
    f:[['Pythagorean','sin\u00b2\u03b8 + cos\u00b2\u03b8 = 1','The unit circle, restated.'],['Angle addition','sin(a+b) = sin a cos b + cos a sin b','Rotation composition.'],['Cosine addition','cos(a+b) = cos a cos b \u2212 sin a sin b','Note the minus.'],['Double angle','sin 2\u03b8 = 2 sin \u03b8 cos \u03b8','Special case of the above.']],
    q:[{t:'mc',q:'If sin \u03b8 = 3/5 and \u03b8 is in the first quadrant, what is cos \u03b8?',o:['4/5','5/4','2/5','\u22124/5'],a:0,e:'From sin\u00b2\u03b8 + cos\u00b2\u03b8 = 1: cos\u00b2\u03b8 = 1 \u2212 9/25 = 16/25, so cos \u03b8 = 4/5. The first quadrant keeps it positive.'},
       {t:'in',q:'Simplify sin\u00b2(x) + cos\u00b2(x) + 4.',a:'5',s:['sin\u00b2(x) + cos\u00b2(x) = 1 for every x.','So the expression is 1 + 4.','= 5'],e:'The Pythagorean identity collapses regardless of x, so nothing is left to depend on the angle.'}]},
  { id:'waves', title:'Waves: amplitude, period, phase', graph:'sine', cs:'Digital audio is a sum of sine waves sampled 44,100 times a second, and the sampling theorem is a statement about periods. Easing curves in UI animation are the same functions with different parameters.', idea:'Amplitude stretches a wave vertically, period stretches it horizontally, phase slides it sideways.',
    f:[['General sine','y = A sin(Bx + C) + D','A amplitude, D offset.'],['Period','T = 2\u03c0 / B','Bigger B, faster wave.'],['Frequency','f = 1 / T','Cycles per unit.']],
    q:[{t:'mc',q:'What is the period of y = sin(4x)?',o:['4\u03c0','2\u03c0','\u03c0/2','\u03c0/4'],a:2,e:'Period is 2\u03c0/B with B = 4, giving \u03c0/2. The wave completes four cycles in the space one normally takes.'},
       {t:'in',q:'A signal repeats every 0.005 seconds. What is its frequency in hertz?',a:'200',s:['Frequency is the reciprocal of the period.','f = 1 / 0.005','= 200 Hz'],e:'Period and frequency always trade off as reciprocals.'}]},
  { id:'law-sines', title:'Laws of sines and cosines', cs:'These two laws solve triangles with no right angle \u2014 which is every triangle in a navigation fix, a mesh in a 3D model, or a triangulated sensor reading.', idea:'They extend SOH-CAH-TOA to any triangle: sines relate sides to opposite angles, cosines generalise Pythagoras.',
    f:[['Law of sines','a/sin A = b/sin B = c/sin C','Side over opposite sine is constant.'],['Law of cosines','c\u00b2 = a\u00b2 + b\u00b2 \u2212 2ab cos C','Pythagoras plus a correction term.'],['Right-angle check','C = 90\u00b0 \u21d2 cos C = 0','The correction vanishes \u2014 Pythagoras returns.'],['Triangle area','\u00bd ab sin C','No height needed.']],
    q:[{t:'mc',q:'When the angle C in the law of cosines is 90\u00b0, the formula reduces to what?',o:['The law of sines','a\u00b2 + b\u00b2 = c\u00b2','c = a + b','Nothing meaningful'],a:1,e:'cos 90\u00b0 = 0, so the \u22122ab cos C term disappears, leaving Pythagoras exactly. The law of cosines is Pythagoras with a correction for how far the angle is from 90\u00b0.'},
       {t:'in',q:'A triangle has sides a = 3, b = 4 and included angle C = 90\u00b0. Find side c.',a:'5',s:['c\u00b2 = a\u00b2 + b\u00b2 \u2212 2ab cos C, and cos 90\u00b0 = 0.','c\u00b2 = 9 + 16 = 25.','c = 5'],e:'The 3-4-5 triangle again \u2014 the law of cosines agrees with Pythagoras where they overlap.'}]},
  { id:'inverse-trig', title:'Inverse trig and atan2', cs:'Turning a vector back into an angle is atan2, the most-called trig function in graphics and robotics. Plain arctangent loses the quadrant; atan2 keeps it, and knowing why saves hours of debugging.', idea:'Inverse trig functions answer the reverse question: which angle produced this ratio?',
    f:[['Arcsine','sin\u207b\u00b9(x), range \u2212\u03c0/2..\u03c0/2','Only defined for \u22121 \u2264 x \u2264 1.'],['Arctangent','tan\u207b\u00b9(x), range \u2212\u03c0/2..\u03c0/2','Covers only two quadrants.'],['atan2','atan2(y, x), range \u2212\u03c0..\u03c0','Uses both signs \u2014 all four quadrants.'],['Round trip','sin(sin\u207b\u00b9 x) = x','But sin\u207b\u00b9(sin \u03b8) may not be \u03b8.']],
    q:[{t:'mc',q:'Why does atan2 take two arguments instead of one ratio?',o:['For extra precision','The signs of y and x separately determine the quadrant; the ratio alone cannot','It is faster','To avoid division by zero only'],a:1,e:'The ratio y/x is identical for (1,1) and (\u22121,\u22121), but those point in opposite directions. Keeping the two signs separate recovers the full \u2212\u03c0..\u03c0 range \u2014 and, as a bonus, x = 0 stops being an error.'},
       {t:'in',q:'What is sin\u207b\u00b9(1) as a multiple of \u03c0? Enter the denominator d in \u03c0/d.',a:'2',s:['Ask: which angle has sine 1?','The sine reaches 1 at the top of the unit circle.','That is \u03c0/2, so d = 2.'],e:'Reading inverse trig off the unit circle beats memorising tables.'}]},
]},

{ id:'precalc', n:'Precalculus', sub:'The functions calculus is about to differentiate', lessons:[
  { id:'transformations', title:'Transformations of functions', graph:'shift', cs:'Shifting and scaling a function is the same arithmetic as mapping data coordinates to screen pixels, which every chart and every camera does.', idea:'Changes outside the function move the output; changes inside move the input, and backwards.',
    f:[['Vertical shift','f(x) + k','Up by k.'],['Horizontal shift','f(x \u2212 h)','Right by h, despite the minus.'],['Scaling','a\u00b7f(bx)','a stretches y, b compresses x.']],
    q:[{t:'mc',q:'How does y = f(x \u2212 3) compare to y = f(x)?',o:['Shifted 3 left','Shifted 3 right','Shifted 3 down','Stretched by 3'],a:1,e:'Inside changes act in reverse: subtracting 3 from the input means x must be 3 larger to reach the same output, so the graph moves right.'},
       {t:'in',q:'The graph of y = x\u00b2 is moved up 5 and right 2. Give the new equation using (x \u2212 h)\u00b2 + k form; enter the value of h.',a:'2',s:['Right by 2 means replacing x with (x \u2212 2).','Up by 5 adds 5 outside.','y = (x \u2212 2)\u00b2 + 5, so h = 2.'],e:'Horizontal moves live inside the bracket with the opposite sign.'}]},
  { id:'exponential', title:'Exponential growth', graph:'exp', cs:'Exponential growth is what a brute-force search over subsets does: 2\u207f. It is why an algorithm that is fine at n = 20 is impossible at n = 60.', idea:'Exponential growth multiplies by a constant factor each step, rather than adding one.',
    f:[['Growth model','y = a\u00b7b\u02e3','b > 1 grows, b < 1 decays.'],['Doubling','2\u207f doubles every step','n = 60 is about 10\u00b9\u2078.'],['Continuous','A = Pe\u02b3\u1d57','Interest, decay, cooling.']],
    q:[{t:'mc',q:'A brute-force algorithm checks every subset of n items. At n = 20 it takes 1 second. Roughly how long at n = 30?',o:['1.5 seconds','30 seconds','17 minutes','10 hours'],a:2,e:'Ten more items multiplies the work by 2\u00b9\u2070 = 1024, so about 1024 seconds, which is roughly 17 minutes. Ten more again would be about 12 days.'},
       {t:'in',q:'A culture doubles every hour and starts at 500. How many after 4 hours?',a:'8000',s:['Each hour multiplies by 2.','After 4 hours the factor is 2\u2074 = 16.','500 \u00d7 16 = 8000'],e:'Doubling time turns repeated multiplication into a single power.'}]},
  { id:'logarithms', title:'Logarithms', demo:'binarySearch', cs:'Every time you halve a problem instead of walking through it, a logarithm appears in the running time. Binary search, balanced trees, merge sort and heap operations are all O(log n).', idea:'A logarithm asks a counting question: how many times do I multiply the base by itself to get here?',
    f:[['Definition','log_b(x) = y \u27fa b\u02b8 = x','Same fact, two directions.'],['Product rule','log(xy) = log x + log y','Multiplication becomes addition.'],['Power rule','log(x\u207f) = n log x','Exponents come out front.'],['Change of base','log_b x = ln x / ln b','Why Big-O ignores the base.']],
    q:[{t:'mc',q:'A sorted array holds 1,048,576 records. Worst-case comparisons for a binary search?',o:['20','512','1,024','1,000,000'],a:0,e:'Each comparison discards half the array, so the count is how many halvings reduce 1,048,576 to 1: log\u2082(1,048,576) = 20, because 2\u00b2\u2070 = 1,048,576. A linear scan would take up to a million.'},
       {t:'in',q:'Evaluate log\u2082(8) + log\u2082(4).',a:'5',s:['log\u2082(8) = 3 because 2\u00b3 = 8.','log\u2082(4) = 2 because 2\u00b2 = 4.','3 + 2 = 5. Equivalently log\u2082(8\u00b74) = log\u2082(32) = 5.'],e:'The product rule means adding logs is multiplying the arguments.'}]},
  { id:'sequences', title:'Sequences and series', graph:'seq', cs:'The cost of a recursive algorithm is a recurrence relation, and the total cost of a dynamic array\u2019s resizes is a geometric series that sums to a constant per insert.', idea:'A sequence lists terms; a series adds them up.',
    f:[['Arithmetic term','a\u2099 = a\u2081 + (n\u22121)d','Constant difference.'],['Arithmetic sum','S\u2099 = n(a\u2081 + a\u2099)/2','Pair the ends.'],['Geometric sum','S\u2099 = a(1 \u2212 r\u207f)/(1 \u2212 r)','Constant ratio.'],['Infinite geometric','S = a/(1 \u2212 r), |r| < 1','Converges.']],
    q:[{t:'mc',q:'What is 1 + 1/2 + 1/4 + 1/8 + \u22ef ?',o:['\u221e','1.5','2','e'],a:2,e:'This is an infinite geometric series with a = 1 and r = 1/2, so the sum is 1/(1 \u2212 1/2) = 2. This exact sum is why doubling a dynamic array gives amortised constant-time appends.'},
       {t:'in',q:'Sum the integers from 1 to 100.',a:'5050',s:['This is arithmetic with a\u2081 = 1, a\u2099 = 100, n = 100.','S = n(a\u2081 + a\u2099)/2 = 100(101)/2.','= 5050'],e:'Pairing 1 with 100, 2 with 99 and so on gives fifty pairs of 101.'}]},
  { id:'piecewise', title:'Piecewise and step functions', graph:'relu', cs:'ReLU \u2014 the most-used activation function in deep learning \u2014 is a two-piece function: zero, then the identity. Tax brackets, rate limits and tiered pricing are all piecewise definitions running in production.', idea:'A piecewise function applies a different rule on each region of its domain.',
    f:[['Definition','f(x) = rule\u2081 if condition, else rule\u2082','An if/else in math clothing.'],['Absolute value','|x| = x if x \u2265 0, else \u2212x','The simplest piecewise function.'],['ReLU','max(0, x)','Zero below, identity above.'],['Continuity check','Pieces must meet at the seams','Or the function jumps.']],
    q:[{t:'mc',q:'ReLU(x) = max(0, x). What is ReLU(\u22125) + ReLU(3)?',o:['\u22122','3','8','0'],a:1,e:'ReLU clips negatives to zero: ReLU(\u22125) = 0 and ReLU(3) = 3, so the sum is 3. That one-sided clipping is what lets deep networks model non-linear behaviour.'},
       {t:'in',q:'f(x) = x\u00b2 for x < 2 and f(x) = 3x + c for x \u2265 2. What c makes the pieces meet at x = 2?',a:'-2',alt:['\u22122'],s:['Left piece at 2: 2\u00b2 = 4.','Right piece at 2: 6 + c.','Meeting requires 6 + c = 4, so c = \u22122.'],e:'Matching values at the seam is exactly a continuity condition.'}]},
  { id:'binomial', title:'The binomial theorem', cs:'Expanding (1 + x)\u207f is where the C(n,k) coefficients from counting meet algebra, and it is why the binomial distribution is called binomial. Pascal\u2019s triangle is a dynamic program you can run by hand.', idea:'The coefficients of (a + b)\u207f are counts: how many ways to choose b from n factors.',
    f:[['Binomial theorem','(a+b)\u207f = \u03a3 C(n,k) a\u207f\u207b\u1d4f b\u1d4f','Coefficients are combinations.'],['Pascal\u2019s rule','C(n,k) = C(n\u22121,k\u22121) + C(n\u22121,k)','Each entry sums the two above.'],['Row sum','\u03a3 C(n,k) = 2\u207f','All subsets, again.'],['Square case','(a+b)\u00b2 = a\u00b2 + 2ab + b\u00b2','The row 1 2 1.']],
    q:[{t:'mc',q:'What is the coefficient of x\u00b2 in (1 + x)\u2074?',o:['2','4','6','8'],a:2,e:'The coefficient is C(4,2) = 6: from four factors of (1 + x), choose which two contribute an x. The expansion is 1 + 4x + 6x\u00b2 + 4x\u00b3 + x\u2074 \u2014 Pascal\u2019s row 1 4 6 4 1.'},
       {t:'in',q:'Sum all coefficients in row n = 5 of Pascal\u2019s triangle.',a:'32',s:['The row sums to 2\u207f.','2\u2075 = 32.','Equivalently: substitute a = b = 1 into (a+b)\u2075.'],e:'The row sum counting all subsets is the same 2\u207f from the sets lesson.'}]},
]},

{ id:'calc1', n:'Calculus I', sub:'Limits and derivatives', lessons:[
  { id:'limits', title:'Limits and continuity', graph:'limit', cs:'Asymptotic analysis is a limit: Big-O asks what a cost function does as n goes to infinity, ignoring everything that stops mattering.', idea:'A limit is the value a function approaches, whether or not it ever arrives.',
    f:[['Notation','lim(x\u2192a) f(x) = L','Approach, not arrival.'],['Continuity','lim(x\u2192a) f(x) = f(a)','No jump, no hole.'],['Dominant term','Highest power wins as x \u2192 \u221e','The rule behind Big-O.']],
    q:[{t:'mc',q:'What is lim(x\u2192\u221e) (3x\u00b2 + 5x)/(x\u00b2 + 1)?',o:['0','3','\u221e','5'],a:1,e:'Divide top and bottom by x\u00b2: (3 + 5/x)/(1 + 1/x\u00b2). The 5/x and 1/x\u00b2 terms vanish, leaving 3. This is precisely why 3n\u00b2 + 5n is \u0398(n\u00b2).'},
       {t:'in',q:'Evaluate lim(x\u21923) (x\u00b2 \u2212 9)/(x \u2212 3).',a:'6',s:['Direct substitution gives 0/0, which is undefined.','Factor the top: x\u00b2 \u2212 9 = (x \u2212 3)(x + 3).','Cancel (x \u2212 3), leaving x + 3.','Substitute x = 3: 3 + 3 = 6.'],e:'The hole at x = 3 does not stop the function from approaching 6.'}]},
  { id:'derivatives', title:'Derivatives', graph:'tangent', cs:'Gradient descent, the training loop behind essentially every machine learning model, moves parameters in the direction the derivative says the error falls fastest.', idea:'A derivative is an instantaneous rate of change: the slope of the curve at one point.',
    f:[['Definition','f\u2032(x) = lim(h\u21920) [f(x+h) \u2212 f(x)]/h','A slope with a shrinking run.'],['Power rule','d/dx x\u207f = n x\u207f\u207b\u00b9','Drop it down, subtract one.'],['Product rule','(fg)\u2032 = f\u2032g + fg\u2032','Not the product of derivatives.'],['Common','d/dx e\u02e3 = e\u02e3, d/dx ln x = 1/x','Worth memorising.']],
    q:[{t:'mc',q:'What is the derivative of f(x) = 4x\u00b3?',o:['12x\u00b2','4x\u00b2','12x\u00b3','3x\u00b2'],a:0,e:'Power rule: bring the 3 down and reduce the exponent, giving 3 \u00b7 4x\u00b2 = 12x\u00b2.'},
       {t:'in',q:'Find f\u2032(2) for f(x) = x\u00b2 + 3x.',a:'7',s:['Differentiate term by term: f\u2032(x) = 2x + 3.','Substitute x = 2: 2(2) + 3.','= 7'],e:'The curve is climbing seven units of output per unit of input at that point.'}]},
  { id:'chain-rule', title:'The chain rule', cs:'Backpropagation is the chain rule applied layer by layer through a network. Every gradient in a deep model is a long product of local derivatives.', idea:'To differentiate a function of a function, multiply the outer rate by the inner rate.',
    f:[['Chain rule','(f(g(x)))\u2032 = f\u2032(g(x)) \u00b7 g\u2032(x)','Outer, then inner.'],['Example','d/dx (3x + 1)\u2075 = 15(3x + 1)\u2074','The inner 3 must appear.'],['Leibniz form','dy/dx = dy/du \u00b7 du/dx','Rates compose by multiplying.']],
    q:[{t:'mc',q:'What is d/dx sin(5x)?',o:['cos(5x)','5cos(5x)','5sin(5x)','cos(5)'],a:1,e:'Differentiate the outer sine to get cos(5x), then multiply by the derivative of the inner 5x, which is 5.'},
       {t:'in',q:'Find d/dx (x\u00b2 + 1)\u00b3 at x = 1.',a:'24',s:['Outer derivative: 3(x\u00b2 + 1)\u00b2.','Inner derivative: 2x.','So f\u2032(x) = 3(x\u00b2 + 1)\u00b2 \u00b7 2x = 6x(x\u00b2 + 1)\u00b2.','At x = 1: 6 \u00b7 1 \u00b7 (2)\u00b2 = 24.'],e:'If you answered 12, you dropped the inner factor of 2x \u2014 the most common chain-rule slip.'}]},
  { id:'optimization', title:'Optimisation and critical points', cs:'Minimising a loss function is finding where its derivative is zero. The same reasoning finds the batch size or buffer length that minimises total cost.', idea:'At a maximum or minimum, the slope is momentarily flat.',
    f:[['Critical point','f\u2032(x) = 0 or undefined','Candidate extremes.'],['Second derivative test','f\u2033 > 0 minimum, f\u2033 < 0 maximum','Curvature decides.'],['Closed interval','Also check the endpoints','Extremes can hide there.']],
    q:[{t:'mc',q:'For f(x) = x\u00b2 \u2212 6x + 5, where is the minimum?',o:['x = 0','x = 3','x = 5','x = 6'],a:1,e:'f\u2032(x) = 2x \u2212 6, which is zero at x = 3. Since f\u2033 = 2 > 0 the curve opens upward, so x = 3 is a minimum.'},
       {t:'in',q:'A rectangle has perimeter 40. What width maximises its area?',a:'10',s:['If width is w, the height is 20 \u2212 w.','Area A(w) = w(20 \u2212 w) = 20w \u2212 w\u00b2.','A\u2032(w) = 20 \u2212 2w, which is zero at w = 10.','A\u2033 = \u22122 < 0, so this is a maximum.'],e:'The optimum is a square, which is the general answer for fixed-perimeter rectangles.'}]},
  { id:'product-quotient', title:'Product and quotient rules', cs:'Real formulas are products and quotients of simpler ones \u2014 signal times envelope, cost over throughput. These two rules plus the chain rule differentiate everything you will meet.', idea:'The derivative of a product is not the product of derivatives; each factor takes a turn being differentiated.',
    f:[['Product rule','(fg)\u2032 = f\u2032g + fg\u2032','Each factor differentiated once.'],['Quotient rule','(f/g)\u2032 = (f\u2032g \u2212 fg\u2032)/g\u00b2','Low d-high minus high d-low.'],['Sanity check','f = g = x: (x\u00b2)\u2032 = 2x','f\u2032g\u2032 = 1 would be wrong.'],['Reciprocal','(1/g)\u2032 = \u2212g\u2032/g\u00b2','Quotient rule with f = 1.']],
    q:[{t:'mc',q:'What is the derivative of x\u00b7e\u02e3?',o:['e\u02e3','x\u00b7e\u02e3','e\u02e3(x + 1)','e\u02e3(x \u2212 1)'],a:2,e:'Product rule: (x)\u2032e\u02e3 + x(e\u02e3)\u2032 = e\u02e3 + xe\u02e3 = e\u02e3(x + 1). Multiplying the derivatives would give just e\u02e3, which fails at every x except 0.'},
       {t:'in',q:'f(x) = x\u00b2 \u00b7 x\u00b3. Use the product rule and evaluate f\u2032(1).',a:'5',s:['Product rule: (x\u00b2)\u2032x\u00b3 + x\u00b2(x\u00b3)\u2032 = 2x\u00b7x\u00b3 + x\u00b2\u00b73x\u00b2.','= 2x\u2074 + 3x\u2074 = 5x\u2074 \u2014 which is (x\u2075)\u2032, as it must be.','At x = 1: 5.'],e:'The two routes agreeing is the best check the rule is right.'}]},
  { id:'curve-sketching', title:'Reading curves from derivatives', cs:'A latency graph, a loss curve, a profiler trace \u2014 the job is always the same: where is it rising, where does it bend, where does it settle. First and second derivatives answer all three.', idea:'The first derivative says rising or falling; the second says bending up or down.',
    f:[['Increasing','f\u2032 > 0','Graph climbs.'],['Concave up','f\u2033 > 0','Bends like a cup \u2014 rate is rising.'],['Inflection point','f\u2033 changes sign','The bend flips.'],['Local max','f\u2032 = 0 and f\u2033 < 0','Peak of a hill.']],
    q:[{t:'mc',q:'A training loss curve is falling but concave up. What does that mean?',o:['Loss is rising','Loss falls at a slowing rate \u2014 diminishing returns','Loss falls faster and faster','Training has diverged'],a:1,e:'f\u2032 < 0 says falling, f\u2033 > 0 says the slope itself is increasing toward zero \u2014 the fall is levelling off. That is the classic \u201cconverging\u201d shape, and the moment to consider stopping.'},
       {t:'in',q:'f(x) = x\u00b3 \u2212 3x. f\u2032(x) = 3x\u00b2 \u2212 3 is zero at x = \u00b11. Given f\u2033(x) = 6x, is x = 1 a max or a min? Enter max or min.',a:'min',s:['Second derivative test: f\u2033(1) = 6 > 0.','Positive second derivative means concave up.','Concave up at a flat point is a local minimum.'],e:'At x = \u22121, f\u2033 = \u22126 < 0: the mirror-image maximum.'}]},
]},

{ id:'calc2', n:'Calculus II', sub:'Integrals, series and approximation', lessons:[
  { id:'integrals', title:'Integrals and area', demo:'riemann', cs:'An integral accumulates: total error over a run, expected value over a continuous distribution, or the work done summing infinitely many small pieces. Numerical integration is a loop adding rectangles.', idea:'An integral is a sum of infinitely many infinitely thin slices.',
    f:[['Fundamental theorem','\u222b\u2090\u1d47 f\u2032(x) dx = f(b) \u2212 f(a)','Integration undoes differentiation.'],['Power rule','\u222b x\u207f dx = x\u207f\u207a\u00b9/(n+1) + C','For n \u2260 \u22121.'],['Common','\u222b 1/x dx = ln|x| + C','The n = \u22121 exception.']],
    q:[{t:'mc',q:'Evaluate \u222b\u2080\u00b3 2x dx.',o:['6','9','3','18'],a:1,e:'The antiderivative of 2x is x\u00b2. Evaluating from 0 to 3 gives 9 \u2212 0 = 9. Geometrically this is a triangle with base 3 and height 6, area 9.'},
       {t:'in',q:'Evaluate \u222b\u2081\u00b2 3x\u00b2 dx.',a:'7',s:['Antiderivative of 3x\u00b2 is x\u00b3.','Evaluate at the bounds: 2\u00b3 \u2212 1\u00b3.','= 8 \u2212 1 = 7'],e:'The fundamental theorem turns an area problem into two substitutions.'}]},
  { id:'techniques', title:'Techniques of integration', cs:'Substitution and parts are the pattern-matching half of calculus; recognising which to apply is the same skill as recognising which algorithm a problem is asking for.', idea:'Every technique is an attempt to turn an unfamiliar integral into one you already know.',
    f:[['u-substitution','\u222b f(g(x))g\u2032(x) dx = \u222b f(u) du','The chain rule, reversed.'],['By parts','\u222b u dv = uv \u2212 \u222b v du','The product rule, reversed.'],['Choosing u','LIATE order','Log, inverse, algebraic, trig, exponential.']],
    q:[{t:'mc',q:'Which technique best fits \u222b x\u00b7e\u02e3 dx?',o:['u-substitution','Integration by parts','Partial fractions','Trig substitution'],a:1,e:'Two unrelated factors, one of which simplifies when differentiated, is the signature of integration by parts. Taking u = x reduces it to \u222b e\u02e3 dx.'},
       {t:'in',q:'For \u222b 2x(x\u00b2 + 1)\u2075 dx, what should u be? Enter the expression.',a:'x^2+1',alt:['x\u00b2+1','x^2 + 1','x\u00b2 + 1'],s:['Look for an inner function whose derivative is also present.','The derivative of x\u00b2 + 1 is 2x, which is sitting right there.','So u = x\u00b2 + 1 and du = 2x dx, turning the integral into \u222b u\u2075 du.'],e:'u-substitution works exactly when the inner function\u2019s derivative is a factor.'}]},
  { id:'series', title:'Series and convergence', cs:'The total cost of doubling a dynamic array is a geometric series that converges, which is why appending is amortised O(1) despite occasional expensive copies.', idea:'An infinite sum can still be finite if the terms shrink fast enough.',
    f:[['Geometric','\u03a3 ar\u207f = a/(1 \u2212 r), |r| < 1','Converges only inside that range.'],['Harmonic','\u03a3 1/n diverges','Slowly, but it does.'],['Ratio test','lim |a\u2099\u208a\u2081/a\u2099| < 1 converges','The workhorse test.']],
    q:[{t:'mc',q:'Which series converges?',o:['\u03a3 1/n','\u03a3 1/n\u00b2','\u03a3 n','\u03a3 2\u207f'],a:1,e:'\u03a3 1/n\u00b2 converges to \u03c0\u00b2/6. The harmonic series \u03a3 1/n diverges even though its terms go to zero, which is the classic warning that shrinking terms are not enough.'},
       {t:'in',q:'Evaluate \u03a3 from n = 0 to \u221e of (1/3)\u207f.',a:'1.5',alt:['3/2'],s:['This is geometric with a = 1 and r = 1/3.','S = a/(1 \u2212 r) = 1/(1 \u2212 1/3).','= 1/(2/3) = 3/2 = 1.5'],e:'Ratios below one in absolute value always give a finite sum.'}]},
  { id:'taylor', title:'Taylor series', cs:'The sin and exp functions in your standard library are polynomial approximations under the hood, chosen so the error stays below one unit in the last place.', idea:'A Taylor series rebuilds a function from its derivatives at a single point.',
    f:[['Taylor form','f(x) = \u03a3 f\u207d\u207f\u207e(a)(x\u2212a)\u207f/n!','Around a.'],['e\u02e3','1 + x + x\u00b2/2! + x\u00b3/3! + \u22ef','Converges everywhere.'],['sin x','x \u2212 x\u00b3/3! + x\u2075/5! \u2212 \u22ef','Odd powers only.']],
    q:[{t:'mc',q:'The first two terms of the series for sin x give which approximation for small x?',o:['sin x \u2248 1','sin x \u2248 x','sin x \u2248 x\u00b2','sin x \u2248 1 \u2212 x'],a:1,e:'The series starts x \u2212 x\u00b3/6, and for small x the cubic term is negligible, leaving sin x \u2248 x. This small-angle approximation is used constantly in physics and graphics.'},
       {t:'in',q:'Using 1 + x + x\u00b2/2, approximate e^0.1 to three decimal places.',a:'1.105',s:['x = 0.1.','1 + 0.1 = 1.1.','x\u00b2/2 = 0.01/2 = 0.005.','1.1 + 0.005 = 1.105. The true value is 1.10517.'],e:'Three terms already give four correct digits for small x.'}]},
  { id:'applications', title:'Areas, volumes and averages', cs:'The average value of a function is how you turn a fluctuating load curve into one billing number, and volumes of revolution are how CAD software weighs a part before it is machined.', idea:'Every application of the integral is the same move: slice, approximate each slice simply, sum.',
    f:[['Area between curves','\u222b (top \u2212 bottom) dx','Slice vertically.'],['Average value','(1/(b\u2212a)) \u222b\u2090\u1d47 f dx','Total divided by width.'],['Disk volume','V = \u03c0 \u222b f(x)\u00b2 dx','Each slice is a circle.'],['Accumulated change','\u222b rate dt = total','The odometer from the speedometer.']],
    q:[{t:'mc',q:'A server\u2019s load is f(t) = 6t on t \u2208 [0, 4] (requests/s). What is the average load?',o:['6','12','24','48'],a:1,e:'Average = (1/4)\u222b\u2080\u2074 6t dt = (1/4)(3t\u00b2 |\u2080\u2074) = 48/4 = 12. The average of a linear ramp is its midpoint value, which is a useful sanity check.'},
       {t:'in',q:'Find the area between y = x and y = x\u00b2 from x = 0 to x = 1, as a fraction.',a:'1/6',s:['On [0,1] the line is on top: \u222b (x \u2212 x\u00b2) dx.','Antiderivative: x\u00b2/2 \u2212 x\u00b3/3.','At 1: 1/2 \u2212 1/3 = 1/6; at 0: 0.'],e:'Top minus bottom keeps the area positive without thinking about signs.'}]},
  { id:'improper', title:'Improper integrals', cs:'An unbounded tail with a finite total is why an expected value over an infinite range can still be a real number \u2014 the calculation behind every long-tail latency or lifetime-value model.', idea:'An improper integral extends the bounds to infinity and asks whether the accumulated area settles.',
    f:[['Definition','\u222b\u2081\u221e f dx = lim(b\u2192\u221e) \u222b\u2081\u1d47 f dx','A limit of ordinary integrals.'],['p-test','\u222b\u2081\u221e 1/x\u1d56 dx converges \u21d4 p > 1','The integral twin of the p-series.'],['Boundary case','\u222b\u2081\u221e 1/x dx = \u221e','ln x grows without bound.'],['Tail comparison','0 \u2264 f \u2264 g, \u222bg finite \u21d2 \u222bf finite','Squeeze the tail.']],
    q:[{t:'mc',q:'Which improper integral converges?',o:['\u222b\u2081\u221e 1/x dx','\u222b\u2081\u221e 1/\u221ax dx','\u222b\u2081\u221e 1/x\u00b2 dx','\u222b\u2081\u221e x dx'],a:2,e:'The p-test: 1/x\u00b2 has p = 2 > 1 and converges (to exactly 1). Both 1/x and 1/\u221ax fail with p \u2264 1 \u2014 shrinking toward zero is not enough, the shrink has to be fast enough.'},
       {t:'in',q:'Evaluate \u222b\u2081\u221e 1/x\u00b2 dx.',a:'1',s:['Antiderivative of x\u207b\u00b2 is \u2212x\u207b\u00b9.','At b: \u22121/b \u2192 0 as b \u2192 \u221e.','Minus the value at 1: 0 \u2212 (\u22121) = 1.'],e:'An infinitely long region with total area exactly 1 \u2014 the picture behind every convergent tail.'}]},
]},

{ id:'discrete', n:'Discrete math', sub:'Logic, sets and proof', lessons:[
  { id:'logic', title:'Propositional logic', demo:'truthTable', cs:'Every if statement is a proposition, and De Morgan\u2019s laws are what let you rewrite !(a && b) as !a || !b when simplifying a condition.', idea:'A proposition is a statement that is definitely true or definitely false, and connectives build bigger ones.',
    f:[['Implication','p \u2192 q \u2261 \u00acp \u2228 q','False only when p true, q false.'],['De Morgan','\u00ac(p \u2227 q) \u2261 \u00acp \u2228 \u00acq','Flip the operator, negate both.'],['Contrapositive','p \u2192 q \u2261 \u00acq \u2192 \u00acp','Always equivalent.'],['Converse','q \u2192 p','Not equivalent \u2014 a common error.']],
    q:[{t:'mc',q:'Which is equivalent to \u00ac(p \u2228 q)?',o:['\u00acp \u2228 \u00acq','\u00acp \u2227 \u00acq','p \u2227 q','\u00acp \u2192 q'],a:1,e:'De Morgan: negating an or gives an and of the negations. In code, !(a || b) is the same as !a && !b.'},
       {t:'in',q:'The statement p \u2192 q is false in exactly how many of the four rows of its truth table?',a:'1',s:['p \u2192 q fails only when the premise holds but the conclusion does not.','That is the single row p = true, q = false.','So it is false in 1 row and true in the other 3.'],e:'An implication with a false premise is vacuously true, which surprises most people at first.'}]},
  { id:'sets', title:'Sets and relations', cs:'A hash set is a set with an O(1) membership test, and a database join is a relation being composed. Set operations are the mental model behind query planning.', idea:'A set cares only about membership: no order, no duplicates.',
    f:[['Union / intersection','A \u222a B, A \u2229 B','Or, and.'],['Inclusion\u2013exclusion','|A \u222a B| = |A| + |B| \u2212 |A \u2229 B|','Do not double-count.'],['Power set','|P(A)| = 2\u207f','Every element in or out.'],['Cartesian product','|A \u00d7 B| = |A|\u00b7|B|','All ordered pairs.']],
    q:[{t:'mc',q:'How many subsets does a set of 5 elements have?',o:['5','10','25','32'],a:3,e:'Each element is independently in or out, giving 2\u2075 = 32 subsets, including the empty set and the full set.'},
       {t:'in',q:'|A| = 30, |B| = 20, |A \u2229 B| = 8. What is |A \u222a B|?',a:'42',s:['Inclusion\u2013exclusion: |A| + |B| \u2212 |A \u2229 B|.','30 + 20 = 50.','50 \u2212 8 = 42'],e:'Subtracting the intersection removes the elements counted in both sets.'}]},
  { id:'proofs', title:'Proof techniques', cs:'Arguing that an algorithm is correct is a proof. Loop invariants are induction; showing a bound cannot be beaten is usually contradiction.', idea:'A proof is an argument that leaves no room for a counterexample.',
    f:[['Direct','Assume p, derive q','The default.'],['Contrapositive','Prove \u00acq \u2192 \u00acp','Same truth, easier work.'],['Contradiction','Assume \u00acq, derive nonsense','Good for "no such thing exists".'],['Counterexample','One case disproves a for-all','Cheapest refutation.']],
    q:[{t:'mc',q:'To prove "if n\u00b2 is even then n is even", which approach is easiest?',o:['Direct proof','Contrapositive','Counterexample','Induction'],a:1,e:'The contrapositive is "if n is odd then n\u00b2 is odd", which follows in one line: n = 2k+1 gives n\u00b2 = 4k\u00b2 + 4k + 1, an odd number. The direct version is far more awkward.'},
       {t:'in',q:'How many counterexamples are needed to disprove "every prime is odd"?',a:'1',s:['A universal claim is refuted by a single failing case.','2 is prime and even.','So one counterexample suffices.'],e:'Disproving a for-all is cheap; proving one is not.'}]},
  { id:'induction', title:'Induction and recursion', cs:'Proving a recursive function correct is induction: the base case is the recursion\u2019s stopping condition and the inductive step is the recursive call.', idea:'If the first domino falls and each one knocks the next, they all fall.',
    f:[['Base case','Show P(1)','Or whatever the start is.'],['Inductive step','P(k) \u21d2 P(k+1)','The domino link.'],['Strong induction','Assume all of P(1..k)','For multi-branch recursion.'],['Useful sum','1 + 2 + \u22ef + n = n(n+1)/2','The standard first exercise.']],
    q:[{t:'mc',q:'In proving P(n) for all n \u2265 1, what does the inductive step assume?',o:['P(n) for all n','P(k) for one arbitrary k','P(k+1)','Nothing'],a:1,e:'You assume the statement for an arbitrary k and derive it for k+1. Assuming it for all n would be assuming what you set out to prove.'},
       {t:'in',q:'Using n(n+1)/2, what is 1 + 2 + \u22ef + 20?',a:'210',s:['n = 20.','n(n+1)/2 = 20 \u00b7 21 / 2.','= 420/2 = 210'],e:'This closed form is why a double loop over all pairs is n\u00b2/2, not n\u00b2.'}]},
  { id:'quantifiers', title:'Predicate logic and quantifiers', cs:'Every loop assertion is a quantified statement: "all elements are sorted" is a for-all, "some element matches" is a there-exists. Negating them correctly is what makes a test\u2019s failure condition right.', idea:'A quantifier says how many things a predicate must hold for: all of them, or at least one.',
    f:[['Universal','\u2200x P(x)','True for every x.'],['Existential','\u2203x P(x)','True for at least one x.'],['Negating \u2200','\u00ac\u2200x P(x) \u2261 \u2203x \u00acP(x)','One counterexample.'],['Negating \u2203','\u00ac\u2203x P(x) \u2261 \u2200x \u00acP(x)','None at all.'],['Order matters','\u2200x\u2203y \u2260 \u2203y\u2200x','A very common trap.']],
    q:[{t:'mc',q:'What is the negation of "every element in the array is positive"?',o:['Every element is negative','No element is positive','At least one element is not positive','The array is empty'],a:2,e:'Negating a universal gives an existential of the negation: \u00ac\u2200x P(x) \u2261 \u2203x \u00acP(x). One non-positive element is enough to falsify the claim; you do not need all of them to fail.'},
       {t:'in',q:'Domain {1,2,3}. For how many values is the predicate "x > 1" true?',a:'2',s:['Check each: 1 > 1 is false.','2 > 1 is true, 3 > 1 is true.','So the predicate holds for 2 values, making \u2203x true and \u2200x false.'],e:'Evaluating over a small domain is the fastest way to test a quantified claim.'}]},
  { id:'boolean', title:'Boolean algebra and logic circuits', cs:'Every digital circuit is a Boolean function, and minimising it removes physical gates. This is WGU C959 territory and the direct bridge from logic to hardware.', idea:'Boolean algebra is arithmetic on two values, where simplification means fewer gates.',
    f:[['Identity','x + 0 = x, x \u00b7 1 = x','Neutral elements.'],['Domination','x + 1 = 1, x \u00b7 0 = 0','Absorbing elements.'],['Complement','x + x\u0304 = 1, x \u00b7 x\u0304 = 0','A value and its negation.'],['Absorption','x + xy = x','The classic gate saver.'],['Distribution','x(y + z) = xy + xz','Same as arithmetic.'],['De Morgan','(xy)\u0304 = x\u0304 + \u0233','Flip and negate.']],
    q:[{t:'mc',q:'Simplify x + xy.',o:['x','y','xy','x + y'],a:0,e:'Absorption. Factor to x(1 + y), and since 1 + y = 1 in Boolean algebra, the whole expression is x. The y term is redundant, so an AND gate can be deleted from the circuit.'},
       {t:'in',q:'How many rows does the truth table of a 4-input Boolean function have?',a:'16',s:['Each input independently takes 2 values.','Four inputs: 2\u2074.','= 16 rows'],e:'This doubling is why exhaustive circuit verification becomes impractical past about 30 inputs.'}]},
  { id:'relations', title:'Relations and their properties', cs:'Equality, subtyping, "depends on" and "is reachable from" are all relations. Whether a relation is transitive decides whether you can precompute a closure; whether it is antisymmetric decides whether a topological sort exists.', idea:'A relation is a set of ordered pairs, and its useful properties are named patterns in which pairs appear.',
    f:[['Reflexive','\u2200a: (a,a) \u2208 R','Every element relates to itself.'],['Symmetric','(a,b) \u21d2 (b,a)','Direction does not matter.'],['Antisymmetric','(a,b) and (b,a) \u21d2 a = b','Orderings.'],['Transitive','(a,b) and (b,c) \u21d2 (a,c)','Chains collapse.'],['Equivalence','Reflexive + symmetric + transitive','Partitions the set.'],['Partial order','Reflexive + antisymmetric + transitive','Gives a topological sort.']],
    q:[{t:'mc',q:'Which property does "is less than" (<) on integers have?',o:['Reflexive','Symmetric','Transitive','Equivalence'],a:2,e:'a < b and b < c gives a < c, so it is transitive. It is not reflexive (a < a is false) and not symmetric (a < b rules out b < a), so it is a strict order, not an equivalence.'},
       {t:'in',q:'A set has 3 elements. How many ordered pairs are in A \u00d7 A?',a:'9',s:['Each pair has 3 choices for the first slot and 3 for the second.','3 \u00d7 3.','= 9 pairs, so there are 2\u2079 = 512 possible relations on A.'],e:'Any relation on A is a subset of these 9 pairs.'}]},
  { id:'recurrence', title:'Recurrence relations', cs:'Recursive algorithm costs are recurrences, and so are Fibonacci, compound interest and Tower of Hanoi. Solving one gives a closed form you can evaluate without recursing.', idea:'A recurrence defines each term from earlier terms plus a base case.',
    f:[['Linear homogeneous','a\u2099 = c\u2081a\u2099\u208b\u2081 + c\u2082a\u2099\u208b\u2082','Solve via characteristic equation.'],['Characteristic eq.','r\u00b2 = c\u2081r + c\u2082','Roots give the closed form.'],['Fibonacci','F\u2099 = F\u2099\u208b\u2081 + F\u2099\u208b\u2082','F\u2081 = F\u2082 = 1.'],['Hanoi','H\u2099 = 2H\u2099\u208b\u2081 + 1 \u21d2 2\u207f \u2212 1','Doubling plus one.'],['Divide & conquer','T(n) = aT(n/b) + f(n)','Master theorem territory.']],
    q:[{t:'mc',q:'Tower of Hanoi satisfies H\u2099 = 2H\u2099\u208b\u2081 + 1 with H\u2081 = 1. What is H\u2084?',o:['8','15','16','31'],a:1,e:'Unroll it: H\u2081 = 1, H\u2082 = 3, H\u2083 = 7, H\u2084 = 15. The closed form is 2\u207f \u2212 1, which is why 64 discs would take longer than the age of the universe.'},
       {t:'in',q:'Fibonacci with F\u2081 = F\u2082 = 1. What is F\u2087?',a:'13',s:['1, 1, then each term is the sum of the previous two.','1, 1, 2, 3, 5, 8, 13.','F\u2087 = 13'],e:'Computing this recursively without memoisation makes 25 calls for a 7-term answer.'}]},
  { id:'advanced-counting', title:'Advanced counting', cs:'Pigeonhole proves hash collisions are unavoidable. Inclusion\u2013exclusion is how a query planner sizes an OR of filters. Both appear on WGU C960 directly.', idea:'When a direct count double-counts or overflows, a structural principle fixes it in one step.',
    f:[['Pigeonhole','n items, k boxes, n > k \u21d2 a box has \u2265 2','Collisions are forced.'],['Generalised pigeonhole','Some box has \u2265 \u2308n/k\u2309','A stronger bound.'],['Inclusion\u2013exclusion (2)','|A\u222aB| = |A|+|B|\u2212|A\u2229B|','Undo the overlap.'],['Inclusion\u2013exclusion (3)','Add singles, subtract pairs, add triple','Alternating signs.'],['Stars and bars','C(n+k\u22121, k\u22121)','Identical items into k bins.']],
    q:[{t:'mc',q:'A hash function maps 1000 keys into 100 buckets. What does pigeonhole guarantee?',o:['No collisions occur','Some bucket holds at least 10 keys','Every bucket holds exactly 10','Collisions are merely likely'],a:1,e:'Generalised pigeonhole gives \u23081000/100\u2309 = 10. This is a guarantee, not a probability \u2014 no hash function, however good, can avoid it.'},
       {t:'in',q:'In a group of 13 people, at least how many share a birth month?',a:'2',s:['There are 12 months and 13 people.','\u230813/12\u2309 = 2.','So at least 2 share a month.'],e:'Pigeonhole in its simplest form: more items than boxes forces a repeat.'}]},
  { id:'automata', title:'Modelling computation', cs:'Regular expressions compile to finite state machines, and lexers, protocol parsers and UI state models are all FSMs. WGU C960 calls this modelling computation.', idea:'A finite state machine is a set of states plus rules for moving between them on each input symbol.',
    f:[['FSM','States, alphabet, transitions, accept states','Finite memory only.'],['Regular language','Recognisable by an FSM','Exactly what regex matches.'],['Not regular','Balanced parentheses, a\u207fb\u207f','Needs a stack.'],['Grammar','Rules generating strings','The other direction.'],['Pumping lemma','Proves a language is not regular','Standard tool.']],
    q:[{t:'mc',q:'Why can no regular expression match balanced parentheses to arbitrary depth?',o:['Regex syntax lacks brackets','An FSM has finitely many states and cannot count unbounded depth','It would be too slow','It requires backtracking'],a:1,e:'Matching depth needs unbounded memory, but a finite state machine has a fixed number of states. This is why HTML and JSON need real parsers rather than regex, a limit worth knowing before you try.'},
       {t:'in',q:'An FSM has 4 states and a 2-symbol alphabet. How many transitions must be defined?',a:'8',s:['Every state needs a transition for every symbol.','4 states \u00d7 2 symbols.','= 8 transitions'],e:'A complete deterministic FSM defines exactly one transition per state-symbol pair.'}]},
]},

{ id:'prob', n:'Combinatorics & probability', sub:'Counting, chance and average behaviour', lessons:[
  { id:'counting', title:'Counting rules', cs:'Counting the states a system can reach tells you how large a test matrix or a lookup table needs to be, and whether exhaustive search is even possible.', idea:'Multiply independent choices; add mutually exclusive ones.',
    f:[['Product rule','n\u2081 \u00d7 n\u2082 \u00d7 \u22ef','Choices in sequence.'],['Sum rule','n\u2081 + n\u2082','Disjoint alternatives.'],['With repetition','n\u02b3','r slots, n options each.']],
    q:[{t:'mc',q:'How many 4-character strings use lowercase letters only?',o:['104','26\u2074','4\u00b2\u2076','26 \u00d7 4'],a:1,e:'Each of the four positions independently takes one of 26 letters, so the product rule gives 26\u2074 = 456,976.'},
       {t:'in',q:'A PIN has 4 digits, each 0\u20139, repeats allowed. How many PINs exist?',a:'10000',s:['Each position has 10 options.','Four independent positions: 10 \u00d7 10 \u00d7 10 \u00d7 10.','= 10\u2074 = 10,000'],e:'This is why 4-digit PINs are brute-forceable in under a second.'}]},
  { id:'permutations', title:'Permutations and combinations', cs:'Password space size, the number of possible orderings a scheduler could choose, and the count of k-subsets a search must consider are all these two formulas.', idea:'Permutations care about order; combinations do not.',
    f:[['Permutations','P(n,r) = n!/(n\u2212r)!','Ordered selections.'],['Combinations','C(n,r) = n!/(r!(n\u2212r)!)','Unordered selections.'],['Symmetry','C(n,r) = C(n, n\u2212r)','Choosing who is out.']],
    q:[{t:'mc',q:'How many 3-person committees can be formed from 8 people?',o:['24','56','336','512'],a:1,e:'Order does not matter in a committee, so it is C(8,3) = 8!/(3!\u00b75!) = 56. If the roles were distinct it would be P(8,3) = 336.'},
       {t:'in',q:'Compute C(6,2).',a:'15',s:['C(6,2) = 6!/(2!\u00b74!).','= (6 \u00d7 5)/(2 \u00d7 1)','= 30/2 = 15'],e:'Cancelling the larger factorial keeps the arithmetic small.'}]},
  { id:'probability', title:'Probability basics', cs:'Hash collisions, randomised quicksort pivots and load balancing all depend on probability. The birthday paradox is why 64-bit hashes collide sooner than intuition suggests.', idea:'Probability is a count of favourable outcomes divided by a count of all outcomes.',
    f:[['Basic','P(A) = favourable / total','Equally likely outcomes.'],['Complement','P(\u00acA) = 1 \u2212 P(A)','Often the easier count.'],['Independent','P(A \u2227 B) = P(A)P(B)','Only when independent.'],['Conditional','P(A|B) = P(A \u2227 B)/P(B)','Given that B happened.']],
    q:[{t:'mc',q:'Two fair coins are flipped. What is the probability of at least one head?',o:['1/4','1/2','3/4','1'],a:2,e:'Use the complement: the only way to get no heads is tails-tails, probability 1/4. So at least one head has probability 1 \u2212 1/4 = 3/4.'},
       {t:'in',q:'A fair six-sided die is rolled. What is the probability of a number greater than 4? Give it as a fraction in lowest terms.',a:'1/3',s:['Favourable outcomes: 5 and 6, so 2 of them.','Total outcomes: 6.','2/6 = 1/3'],e:'Counting favourable cases works whenever outcomes are equally likely.'}]},
  { id:'expected-value', title:'Expected value', cs:'Average-case analysis is an expected value: randomised quicksort is O(n log n) expected even though its worst case is O(n\u00b2). Cache hit rates and retry costs are the same calculation.', idea:'Expected value is the long-run average, weighting each outcome by its probability.',
    f:[['Definition','E[X] = \u03a3 x\u1d62 P(x\u1d62)','Weighted average.'],['Linearity','E[X + Y] = E[X] + E[Y]','True even if dependent.'],['Uniform die','E = (n+1)/2','3.5 for a d6.']],
    q:[{t:'mc',q:'What is the expected value of one roll of a fair six-sided die?',o:['3','3.5','4','6'],a:1,e:'Each face has probability 1/6, so E = (1+2+3+4+5+6)/6 = 21/6 = 3.5. The expected value need not be an achievable outcome.'},
       {t:'in',q:'A game pays 10 with probability 0.2 and 0 otherwise. What is the expected payout?',a:'2',s:['E = 10 \u00d7 0.2 + 0 \u00d7 0.8.','= 2 + 0','= 2'],e:'If a ticket costs more than 2, the game loses money for you in the long run.'}]},
  { id:'conditional', title:'Conditional probability and independence', cs:'Cache hit rates given a warm cache, failure rates given a deploy, click rates given a segment \u2014 every metric that matters is conditional. Assuming independence where it fails is how correlated outages surprise people.', idea:'Conditioning shrinks the universe to the cases where the given event happened.',
    f:[['Conditional','P(A|B) = P(A \u2229 B) / P(B)','Renormalise to B\u2019s world.'],['Independence','P(A|B) = P(A)','B tells you nothing about A.'],['Chain rule','P(A \u2229 B) = P(A|B) P(B)','Build joint from conditional.'],['Correlated failure','Independence is an assumption','Verify it, never assume it.']],
    q:[{t:'mc',q:'Two servers each fail with probability 0.01. When is P(both fail) = 0.0001 valid?',o:['Always','Only if the failures are independent','Only if they share a rack','Never'],a:1,e:'Multiplying requires independence. If both servers share a power supply, one failure predicts the other and the joint probability can approach 0.01 \u2014 a hundred times the naive estimate. Correlated failure is why real redundancy is hard.'},
       {t:'in',q:'P(A \u2229 B) = 0.2 and P(B) = 0.5. What is P(A|B)?',a:'0.4',alt:['2/5'],s:['P(A|B) = P(A \u2229 B)/P(B).','= 0.2/0.5.','= 0.4'],e:'Conditioning divides by the probability of the world you now live in.'}]},
  { id:'distributions', title:'The binomial distribution', graph:'binomdist', cs:'How many of 1000 requests fail if each fails at 1%? How many hash slots stay empty? Any count of successes over independent trials is binomial, and it is the first distribution worth knowing cold.', idea:'The binomial distribution counts successes in n independent yes/no trials.',
    f:[['PMF','P(k) = C(n,k) p\u1d4f (1\u2212p)\u207f\u207b\u1d4f','Choose which trials succeed.'],['Mean','E = np','Trials times rate.'],['Variance','np(1\u2212p)','Widest at p = \u00bd.'],['Rare events','np small \u21d2 Poisson approximation','The tail tool.']],
    q:[{t:'mc',q:'1000 requests each fail independently at 1%. What is the expected number of failures?',o:['1','10','100','It cannot be known'],a:1,e:'The mean of a binomial is np = 1000 \u00d7 0.01 = 10. The actual count fluctuates around that with standard deviation about 3, which is why 4 failures in a batch is normal and 40 is an incident.'},
       {t:'in',q:'A fair coin is flipped 3 times. How many of the 8 outcomes contain exactly 2 heads?',a:'3',s:['Choose which 2 of the 3 flips are heads: C(3,2).','= 3 \u2014 HHT, HTH, THH.','So P(exactly 2 heads) = 3/8.'],e:'The C(n,k) in the PMF is doing exactly this counting.'}]},
]},

{ id:'graphs', n:'Graph theory', sub:'Structure of connections', lessons:[
  { id:'representation', title:'Graphs and representation', cs:'The choice between an adjacency matrix and an adjacency list is a space-time trade-off you make in nearly every graph problem: O(V\u00b2) space with O(1) edge lookup, or O(V+E) space with O(deg) lookup.', idea:'A graph is a set of vertices and a set of pairs of them.',
    f:[['Max edges (undirected)','V(V\u22121)/2','Complete graph.'],['Handshake lemma','\u03a3 deg(v) = 2E','Every edge counted twice.'],['Density','Sparse if E \u2248 V, dense if E \u2248 V\u00b2','Drives the representation choice.']],
    q:[{t:'mc',q:'A simple undirected graph has 6 vertices. What is the maximum number of edges?',o:['6','12','15','36'],a:2,e:'Every pair of distinct vertices can be joined once: C(6,2) = 6\u00b75/2 = 15.'},
       {t:'in',q:'An undirected graph has 10 edges. What is the sum of all vertex degrees?',a:'20',s:['Each edge contributes 1 to the degree of each endpoint.','So the degree sum is twice the edge count.','2 \u00d7 10 = 20'],e:'The handshake lemma also proves the number of odd-degree vertices is always even.'}]},
  { id:'paths', title:'Paths, connectivity and traversal', cs:'BFS finds the fewest-edges path and is the basis of shortest-path on unweighted graphs; DFS underlies cycle detection, topological sort and connected components.', idea:'Traversal is a systematic way to visit every reachable vertex exactly once.',
    f:[['BFS','Queue, layer by layer','Shortest unweighted path.'],['DFS','Stack or recursion, deep first','Cycles, ordering, components.'],['Complexity','O(V + E)','Adjacency list.'],['Dijkstra','O((V+E) log V)','Non-negative weights.']],
    q:[{t:'mc',q:'Which traversal finds the shortest path in an unweighted graph?',o:['DFS','BFS','Either','Neither'],a:1,e:'BFS explores in order of distance from the source, so the first time it reaches a vertex it has used the fewest possible edges. DFS may reach it by a long detour first.'},
       {t:'in',q:'A graph has 8 vertices and 12 edges. What is the running time of BFS in terms of V + E? Enter the number.',a:'20',s:['BFS visits each vertex once and each edge once.','V + E = 8 + 12.','= 20 operations in order of magnitude.'],e:'This is why adjacency lists are preferred for sparse graphs \u2014 a matrix would force V\u00b2 = 64.'}]},
  { id:'trees', title:'Trees and spanning trees', cs:'A minimum spanning tree is the cheapest way to connect every node, which is how network layout, clustering and some approximation algorithms begin.', idea:'A tree is a connected graph with no cycles, and it has exactly one path between any two vertices.',
    f:[['Edge count','A tree on V vertices has V \u2212 1 edges','Add one more and you get a cycle.'],['Binary tree height','\u2265 log\u2082(n+1) \u2212 1','Balanced is the best case.'],['Kruskal','Sort edges, add if no cycle','Greedy MST.'],['Prim','Grow from one vertex','Greedy MST, other order.']],
    q:[{t:'mc',q:'A tree has 15 vertices. How many edges?',o:['14','15','16','30'],a:0,e:'Every tree on V vertices has exactly V \u2212 1 edges, so 14. Any additional edge would create a cycle.'},
       {t:'in',q:'What is the minimum possible height of a binary tree with 15 nodes, counting the root as height 0?',a:'3',s:['A perfect binary tree of height h holds 2^(h+1) \u2212 1 nodes.','2\u2074 \u2212 1 = 15, so h + 1 = 4.','h = 3'],e:'This is the balanced case that makes tree lookups O(log n).'}]},
  { id:'coloring', title:'Colouring and planarity', cs:'Register allocation in a compiler is graph colouring: variables are vertices, conflicts are edges, and colours are physical registers. Scheduling with conflicts is the same problem.', idea:'A proper colouring gives adjacent vertices different colours, using as few colours as possible.',
    f:[['Chromatic number','\u03c7(G)','Fewest colours needed.'],['Bipartite','\u03c7 = 2 \u27fa no odd cycle','Two-colourable.'],['Four colour theorem','Planar \u21d2 \u03c7 \u2264 4','Maps need only four.'],['Bound','\u03c7 \u2264 \u0394 + 1','\u0394 is max degree.']],
    q:[{t:'mc',q:'What is the chromatic number of a triangle (3 mutually connected vertices)?',o:['1','2','3','4'],a:2,e:'Every vertex is adjacent to both others, so no two can share a colour: three colours are required. Any odd cycle needs at least three.'},
       {t:'in',q:'A compiler finds 4 variables all live at the same time. What is the minimum number of registers needed?',a:'4',s:['All four conflict with each other, forming a complete graph K\u2084.','A complete graph on n vertices needs n colours.','So 4 registers.'],e:'When the graph needs more colours than there are registers, the compiler spills to memory.'}]},
  { id:'dags', title:'DAGs and topological sort', cs:'Build systems, spreadsheet recalculation, package managers and task schedulers all answer one question: what order respects the dependencies? That order exists exactly when the graph has no cycles.', idea:'A directed acyclic graph is a dependency diagram, and a topological sort is any order that never violates an arrow.',
    f:[['DAG','Directed edges, no cycles','Dependencies that can be satisfied.'],['Topological sort','Every edge points forward in the order','Exists \u21d4 no cycle.'],['Kahn\u2019s algorithm','Repeatedly remove a node with no incoming edges','O(V + E).'],['Cycle meaning','A depends on B depends on A','No valid order \u2014 the build fails.']],
    q:[{t:'mc',q:'Your package manager reports \u201ccircular dependency\u201d. In graph terms, what did it find?',o:['A vertex with high degree','A cycle in the dependency graph, so no topological order exists','Too many edges','A disconnected component'],a:1,e:'Topological order exists exactly when the graph is acyclic. A cycle means some package must be installed before itself \u2014 a contradiction no ordering can fix, which is why the tool errors instead of retrying.'},
       {t:'in',q:'A DAG has edges A\u2192B, A\u2192C, B\u2192D, C\u2192D. How many vertices have no incoming edge?',a:'1',s:['Count incoming edges: A has 0, B has 1, C has 1, D has 2.','Only A has none.','Kahn\u2019s algorithm would start there.'],e:'The zero in-degree set is always where a topological sort begins.'}]},
  { id:'bipartite', title:'Bipartite graphs and matching', cs:'Assigning workers to shifts, requests to servers, ads to slots \u2014 two-sided assignment is bipartite matching, one of the most-deployed graph problems in industry.', idea:'A bipartite graph has two camps with edges only across; a matching pairs them off without reuse.',
    f:[['Bipartite','Vertices split into two sets, edges cross only','Two-colourable.'],['Odd cycle test','Bipartite \u21d4 no odd cycle','BFS can check it.'],['Matching','Edge set sharing no vertex','Each node paired at most once.'],['Hall\u2019s condition','Every group of k on one side knows \u2265 k on the other','Perfect matching exists \u21d4 this holds.']],
    q:[{t:'mc',q:'Three workers, three shifts, but workers 1 and 2 can only do shift A. Why is no perfect matching possible?',o:['Too few edges overall','Workers 1 and 2 together know only one shift, violating Hall\u2019s condition','Shifts must equal workers','The graph has a cycle'],a:1,e:'Hall\u2019s condition demands every set of k workers collectively covers at least k shifts. The set {1, 2} covers only {A} \u2014 two workers, one shift \u2014 so someone is necessarily left out, no matter how cleverly you assign.'},
       {t:'in',q:'Is a cycle of length 6 bipartite? Enter 1 for yes, 0 for no.',a:'1',s:['A graph is bipartite exactly when it has no odd cycle.','A 6-cycle is even: alternate the two camps around it.','So yes \u2014 1.'],e:'A 5-cycle would fail: alternating colours around an odd loop forces a clash.'}]},
]},

{ id:'numtheory', n:'Number theory & crypto', sub:'Integers, primes and modular arithmetic', lessons:[
  { id:'modular', title:'Divisibility and modular arithmetic', cs:'Hash tables reduce a hash to a bucket with mod, circular buffers wrap with mod, and integer overflow is arithmetic mod 2\u00b3\u00b2. It is the most-used operation you were never formally taught.', idea:'Modular arithmetic keeps only the remainder, so numbers wrap around a fixed circle.',
    f:[['Congruence','a \u2261 b (mod n) \u27fa n | (a \u2212 b)','Same remainder.'],['Addition','(a + b) mod n = ((a mod n) + (b mod n)) mod n','Reduce early, safely.'],['Multiplication','(ab) mod n = ((a mod n)(b mod n)) mod n','Keeps numbers small.']],
    q:[{t:'mc',q:'What is 17 mod 5?',o:['2','3','3.4','12'],a:0,e:'17 = 3 \u00d7 5 + 2, so the remainder is 2. Modular arithmetic returns the remainder, not the quotient.'},
       {t:'in',q:'A circular buffer holds 8 slots. An index of 19 maps to which slot?',a:'3',s:['Wrap with mod: 19 mod 8.','19 = 2 \u00d7 8 + 3.','Slot 3'],e:'When the size is a power of two this is a bitwise AND, which is why buffer sizes are usually 2\u1d4f.'}]},
  { id:'gcd', title:'GCD and the Euclidean algorithm', cs:'Euclid\u2019s algorithm is one of the oldest algorithms still in daily use, and its extended form computes the modular inverse that RSA decryption depends on.', idea:'The greatest common divisor of two numbers is unchanged if you replace the larger with their remainder.',
    f:[['Euclid','gcd(a,b) = gcd(b, a mod b)','Recurse until b = 0.'],['Product identity','gcd(a,b) \u00b7 lcm(a,b) = ab','One gives the other.'],['Coprime','gcd(a,b) = 1','Required for a modular inverse.'],['B\u00e9zout','ax + by = gcd(a,b)','Extended Euclid finds x, y.']],
    q:[{t:'mc',q:'What is gcd(48, 18)?',o:['2','3','6','9'],a:2,e:'gcd(48,18) \u2192 gcd(18, 48 mod 18 = 12) \u2192 gcd(12, 6) \u2192 gcd(6, 0) = 6. Three steps, no factoring.'},
       {t:'in',q:'Compute lcm(12, 18) using the product identity.',a:'36',s:['gcd(12,18) = 6.','lcm = (12 \u00d7 18)/gcd = 216/6.','= 36'],e:'Computing the gcd first avoids factorising either number.'}]},
  { id:'primes', title:'Primes and factorisation', cs:'RSA security rests on the gap between multiplying two large primes, which is fast, and factoring the product, which is not. The sieve of Eratosthenes is still the practical way to list small primes.', idea:'Every integer above 1 factors into primes in exactly one way.',
    f:[['Fundamental theorem','Unique prime factorisation','Up to order.'],['Trial division bound','Test up to \u221an','Factors come in pairs.'],['Sieve complexity','O(n log log n)','List all primes below n.'],['Fermat\u2019s little theorem','a^(p\u22121) \u2261 1 (mod p)','Basis of primality tests.']],
    q:[{t:'mc',q:'To test whether 101 is prime by trial division, what is the largest divisor you must check?',o:['50','10','11','100'],a:1,e:'Factors pair up around \u221an, so checking up to \u221a101 \u2248 10.05 suffices \u2014 that is divisors up to 10. If none divide it, none above will.'},
       {t:'in',q:'How many distinct prime factors does 60 have?',a:'3',s:['60 = 2 \u00d7 30 = 2 \u00d7 2 \u00d7 15 = 2\u00b2 \u00d7 3 \u00d7 5.','The distinct primes are 2, 3 and 5.','So there are 3.'],e:'Distinct primes ignore multiplicity; counting with multiplicity would give 4.'}]},
  { id:'rsa', title:'Modular exponentiation and RSA', cs:'Exponentiation by squaring computes a\u1d47 mod n in O(log b) multiplications instead of b of them, which is the only reason public-key cryptography runs fast enough to use.', idea:'Repeated squaring turns an exponent into its binary expansion, so the work is proportional to the number of bits.',
    f:[['Square and multiply','a\u00b2\u1d4f = (a\u1d4f)\u00b2','Halve the exponent each step.'],['Cost','O(log b) multiplications','Not O(b).'],['RSA encrypt','c = m\u1d49 mod n','Public key (e, n).'],['RSA decrypt','m = c\u1d48 mod n','d is e\u207b\u00b9 mod \u03c6(n).']],
    q:[{t:'mc',q:'Roughly how many modular multiplications does computing a^1024 mod n take with square-and-multiply?',o:['About 10','About 32','About 512','About 1024'],a:0,e:'1024 = 2\u00b9\u2070, so ten successive squarings suffice. Naive repeated multiplication would take 1023 operations \u2014 a hundredfold difference, and far more at cryptographic key sizes.'},
       {t:'in',q:'Compute 3\u2074 mod 5 by reducing at each step.',a:'1',s:['3\u00b2 = 9, and 9 mod 5 = 4.','3\u2074 = (3\u00b2)\u00b2 \u2261 4\u00b2 = 16 (mod 5).','16 mod 5 = 1'],e:'Reducing after every squaring keeps intermediate values small, which is what makes big-integer crypto practical.'}]},
  { id:'mod-inverse', title:'Modular inverses', cs:'Division does not exist in modular arithmetic \u2014 what exists is multiplying by an inverse, and computing that inverse via extended Euclid is the step that turns an RSA public key into a private one.', idea:'The inverse of a mod n is the number that multiplies with a to give 1.',
    f:[['Definition','a\u00b7a\u207b\u00b9 \u2261 1 (mod n)','Undo multiplication by a.'],['Existence','a\u207b\u00b9 exists \u21d4 gcd(a, n) = 1','Coprime or nothing.'],['How to find it','Extended Euclid: ax + ny = 1','x is the inverse.'],['Prime modulus','Every a \u2260 0 has an inverse mod p','Why crypto loves primes.']],
    q:[{t:'mc',q:'Why does 4 have no inverse mod 8?',o:['4 is even','gcd(4, 8) = 4 \u2260 1, so 4x mod 8 only ever hits multiples of 4','8 is not prime','Inverses only exist for primes'],a:1,e:'4x mod 8 cycles through 0 and 4 forever \u2014 it can never land on 1. An inverse exists exactly when a and n share no factor, which is why prime moduli are so convenient: everything nonzero qualifies.'},
       {t:'in',q:'What is the inverse of 3 mod 7?',a:'5',s:['Search for x with 3x \u2261 1 (mod 7).','3\u00d75 = 15, and 15 mod 7 = 1.','So 3\u207b\u00b9 = 5.'],e:'At crypto scale the search is replaced by extended Euclid, which finds it in logarithmic time.'}]},
  { id:'fermat-euler', title:'Fermat and Euler\u2019s theorems', cs:'These two theorems are why RSA decryption actually recovers the message, and why fast primality tests exist at all. They are the deepest facts in this course that fit on one line.', idea:'Raising to certain powers cycles you back to where you started, mod n.',
    f:[['Fermat\u2019s little theorem','a\u1d56\u207b\u00b9 \u2261 1 (mod p)','p prime, a not divisible by p.'],['Euler\u2019s totient','\u03c6(n) = count of 1..n coprime to n','\u03c6(p) = p \u2212 1 for prime p.'],['Euler\u2019s theorem','a^\u03c6(n) \u2261 1 (mod n)','gcd(a, n) = 1.'],['RSA core','ed \u2261 1 (mod \u03c6(n)) \u21d2 (m\u1d49)\u1d48 \u2261 m','Why decryption inverts encryption.']],
    q:[{t:'mc',q:'By Fermat\u2019s little theorem, what is 2\u2076 mod 7?',o:['0','1','2','6'],a:1,e:'With p = 7 the theorem says a\u2076 \u2261 1 (mod 7) for any a not divisible by 7. Check: 2\u2076 = 64 = 63 + 1. Primality tests run this in reverse: if a\u207f\u207b\u00b9 \u2262 1, n is definitely composite.'},
       {t:'in',q:'What is \u03c6(10), the count of numbers in 1..10 coprime to 10?',a:'4',s:['List numbers sharing no factor with 10 = 2\u00d75.','They are 1, 3, 7, 9.','\u03c6(10) = 4.'],e:'RSA computes \u03c6(pq) = (p\u22121)(q\u22121), which is easy if you know the primes and infeasible if you only know their product.'}]},
]},

{ id:'algo', n:'Algorithm analysis', sub:'From math to running time', lessons:[
  { id:'bigo', title:'Big-O and growth rates', graph:'growth', cs:'Big-O is the shared language for algorithm cost. It is how you compare a hash lookup to a scan, justify an index, and know before writing a line whether an approach can survive a million inputs.', idea:'Big-O keeps only what survives as n grows: the dominant term, stripped of its constant.',
    f:[['Definition','f(n) = O(g(n)) \u27fa f \u2264 c\u00b7g eventually','An upper bound, up to a constant.'],['Hierarchy','1 \u226a log n \u226a n \u226a n log n \u226a n\u00b2 \u226a 2\u207f','Each class dominates the last.'],['Sum rule','O(f + g) = O(max(f, g))','The slowest part wins.'],['Product rule','Nested work multiplies','A loop inside a loop.']],
    q:[{t:'mc',q:'Simplify O(3n\u00b2 + 50n + 7).',o:['O(n)','O(n\u00b2)','O(3n\u00b2)','O(n\u00b2 + n)'],a:1,e:'Drop the constant 3 and the terms that grow slower. As n grows, 50n and 7 become rounding error next to n\u00b2, and constants are invisible to Big-O by definition.'},
       {t:'in',q:'An algorithm performs n log\u2082 n operations. How many at n = 8?',a:'24',s:['log\u2082(8) = 3.','n log\u2082 n = 8 \u00d7 3.','= 24'],e:'This is merge sort\u2019s cost shape: log n levels, n work per level.'}]},
  { id:'loops', title:'Reading cost from loops', cs:'Complexity analysis in practice is reading loops. Recognising the four standard shapes \u2014 straight, nested, triangular, halving \u2014 covers almost every function you will ever review.', idea:'The running time of a loop is the number of times its body executes, and nesting multiplies.',
    f:[['Single loop','for i in 1..n \u21d2 O(n)','Body runs n times.'],['Nested loop','for i.. for j.. \u21d2 O(n\u00b2)','n bodies of n each.'],['Triangular','\u03a3 i = n(n+1)/2 \u21d2 O(n\u00b2)','The all-pairs double loop.'],['Halving loop','while n > 1: n \u00f7= 2 \u21d2 O(log n)','A logarithm in disguise.']],
    q:[{t:'mc',q:'What is the complexity of: for i in 1..n, while j > 1: j \u00f7= 2 (with j starting at n)?',o:['O(n)','O(log n)','O(n log n)','O(n\u00b2)'],a:2,e:'The outer loop runs n times and each inner halving loop runs log n times. Nesting multiplies: n \u00d7 log n. This is the shape of heap sort.'},
       {t:'in',q:'for i in 1..n: for j in 1..i \u2014 total body executions at n = 10?',a:'55',s:['The inner loop runs 1, then 2, then 3, \u2026 up to 10 times.','That sum is n(n+1)/2.','10 \u00d7 11 / 2 = 55'],e:'Half of n\u00b2, but Big-O still calls it O(n\u00b2) \u2014 the constant half is discarded.'}]},
  { id:'recurrences', title:'Divide and conquer', cs:'Merge sort, binary search, quickselect and FFT are all recurrences. Solving T(n) = 2T(n/2) + n once tells you the cost of every algorithm with that splitting shape.', idea:'A recurrence prices an algorithm by pricing its recursive calls plus the work of combining them.',
    f:[['Merge sort','T(n) = 2T(n/2) + n \u21d2 O(n log n)','Two halves plus a merge.'],['Binary search','T(n) = T(n/2) + 1 \u21d2 O(log n)','One half plus a comparison.'],['Recursion depth','Halving \u21d2 log\u2082 n levels','The tree\u2019s height.'],['Level cost','Work per level \u00d7 number of levels','How you solve most of them.']],
    q:[{t:'mc',q:'T(n) = T(n/2) + 1 solves to which class?',o:['O(1)','O(log n)','O(n)','O(n log n)'],a:1,e:'Each step does constant work and halves the problem, so the total is the number of halvings: log\u2082 n. This is binary search\u2019s recurrence.'},
       {t:'in',q:'Merge sort on 32 items: how many levels of splitting?',a:'5',s:['Each level halves: 32 \u2192 16 \u2192 8 \u2192 4 \u2192 2 \u2192 1.','That is log\u2082(32) halvings.','= 5 levels'],e:'Each level does n total merge work, so the whole sort is 5 \u00d7 32 = 160 operations \u2014 n log n.'}]},
  { id:'develop', title:'How to design an algorithm', cs:'Interviews and real work both reward the same method: restate, brute force, find the structure, apply a paradigm, prove and measure. The math in this course is what step three runs on.', idea:'Correct and slow first; the shortcut comes from a property of the problem, not from cleverness with code.',
    f:[['1 \u00b7 Restate','Inputs, outputs, constraints','Say it without jargon.'],['2 \u00b7 Brute force','Enumerate the whole space','Correct first, fast later.'],['3 \u00b7 Find structure','Sortedness, overlap, monotonicity','The property that admits a shortcut.'],['4 \u00b7 Apply a paradigm','Greedy, divide & conquer, DP','Match structure to strategy.'],['5 \u00b7 Prove & measure','Invariant + Big-O','Only then optimise.']],
    q:[{t:'mc',q:'Your brute force is O(2\u207f) and n = 50. What is the productive next move?',o:['Buy faster hardware','Look for structure that prunes or reformulates the search','Rewrite it in a faster language','Parallelise across machines'],a:1,e:'2\u2075\u2070 \u2248 10\u00b9\u2075. Hardware, languages and parallelism buy constant factors; only a structural insight \u2014 overlapping subproblems, sortedness, greedy-safe choices \u2014 changes the exponent.'},
       {t:'in',q:'A brute force checks every pair of 1000 items. How many pairs is that?',a:'499500',s:['Pairs are C(n,2) = n(n\u22121)/2.','1000 \u00d7 999 / 2.','= 499,500'],e:'Half a million is fine. At a million items it is half a trillion \u2014 which is when you need the structure.'}]},
  { id:'amortized', title:'Amortised analysis', graph:'amort', cs:'A dynamic array append is usually one write but occasionally a full copy \u2014 and yet it is honestly advertised as O(1). Amortised analysis is the accounting that makes that claim rigorous.', idea:'Charge each cheap operation a little extra to prepay for the rare expensive one.',
    f:[['Amortised cost','Total cost of n ops / n','An average with a guarantee.'],['Doubling array','Copies cost 1+2+4+\u22ef+n < 2n','The geometric series, again.'],['Accounting method','Bank credit on cheap ops, spend on dear ones','Balance never negative.'],['Not average-case','Worst-case total, spread out','No probability involved.']],
    q:[{t:'mc',q:'How does amortised O(1) differ from average-case O(1)?',o:['They are the same','Amortised is a worst-case guarantee on the total; average-case depends on input probabilities','Amortised is faster','Average-case is a stronger claim'],a:1,e:'Amortised analysis makes no assumptions about inputs: over ANY sequence of n appends the total is under 2n. Average-case O(1), like a hash lookup, can still be beaten by an adversarial input. The two claims fail in different ways.'},
       {t:'in',q:'A dynamic array grows 1 \u2192 2 \u2192 4 \u2192 \u22ef \u2192 64. What is the total number of elements copied?',a:'63',s:['Each resize copies the current size: 1 + 2 + 4 + 8 + 16 + 32.','That geometric sum is 63.','Under 2 \u00d7 64 \u2014 less than two copies per element ever inserted.'],e:'The geometric series from the sequences lesson is doing the heavy lifting.'}]},
  { id:'pnp', title:'P, NP and hardness', cs:'Knowing a problem is NP-hard is a licence to stop hunting for a fast exact algorithm and reach for approximations, heuristics or SAT solvers. It is the most money-saving theorem in the course.', idea:'P is what we can solve fast; NP is what we can check fast; whether they differ is the biggest open question in the field.',
    f:[['P','Solvable in polynomial time','Sorting, shortest paths, matching.'],['NP','Verifiable in polynomial time','Given a solution, checking is fast.'],['NP-hard','At least as hard as everything in NP','SAT, TSP, knapsack, colouring.'],['Reduction','Translate problem A into B','How hardness spreads.'],['Open','P = NP? \u2014 unresolved since 1971','$1M Millennium Prize.']],
    q:[{t:'mc',q:'Your scheduling problem is proven NP-hard. What is the professional response?',o:['Optimise your code until it is fast','Use approximation, heuristics or a SAT solver, and accept near-optimal','Buy more servers','Prove P = NP'],a:1,e:'NP-hardness means no known algorithm avoids exponential worst cases, and none is likely to exist. The industry answer is to change the contract: near-optimal answers, restricted inputs, or off-the-shelf solvers that are fast in practice. Micro-optimising an exponential search changes nothing.'},
       {t:'in',q:'Verifying a filled Sudoku takes seconds; solving may take much longer. Which class does that verification speed place Sudoku in?',a:'NP',s:['NP is defined by fast verification, not fast solving.','A completed grid can be checked in polynomial time.','So generalised Sudoku is in NP \u2014 and it is in fact NP-complete.'],e:'\u201cEasy to check, seemingly hard to solve\u201d is the signature of the whole class.'}]},
]},

{ id:'landmark', n:'Landmark algorithms', sub:'The canonical ten, broken down step by step', lessons:[
  { id:'binary-search', title:'Binary search', demo:'binarySearch', code:"function search(a, target):\n  lo = 0, hi = a.length - 1\n  while lo <= hi:\n    mid = lo + (hi - lo) / 2      // not (lo+hi)/2 — overflow\n    if a[mid] == target: return mid\n    if a[mid] < target:  lo = mid + 1\n    else:                hi = mid - 1\n  return NOT_FOUND                 // O(log n)", cs:'The first algorithm worth knowing cold. It appears directly in sorted lookups, and indirectly everywhere you binary-search an answer space \u2014 rate limiting, capacity planning, and "find the smallest value that works" problems.', idea:'Keep a range that must contain the answer, and halve it every comparison until one element remains.',
    f:[['Precondition','Input must be sorted','Otherwise halving proves nothing.'],['Invariant','If present, target is in [lo, hi]','True before and after every step.'],['Midpoint','mid = lo + (hi \u2212 lo)/2','Written this way to avoid overflow.'],['Cost','O(log n) time, O(1) space','20 comparisons for a million items.']],
    q:[{t:'mc',q:'Why must the input be sorted?',o:['To make the midpoint easy to compute','Because comparing to the midpoint must rule out an entire half','To keep memory contiguous','It does not need to be sorted'],a:1,e:'Sortedness is what licenses the discard. If the array were unordered, learning that the midpoint is too small would tell you nothing about the other elements, and no half could be eliminated.'},
       {t:'in',q:'Worst-case comparisons on 1000 sorted items.',a:'10',s:['Each comparison halves the range.','You need the smallest k with 2\u1d4f \u2265 1000.','2\u2079 = 512 and 2\u00b9\u2070 = 1024, so k = 10.'],e:'\u2308log\u2082 1000\u2309 = 10. Doubling the array adds exactly one comparison.'}]},
  { id:'sorting', title:'Merge sort and quicksort', code:"function mergesort(a):\n  if a.length <= 1: return a\n  L = mergesort(left half)\n  R = mergesort(right half)\n  return merge(L, R)               // T(n) = 2T(n/2) + n\n\nfunction quicksort(a, lo, hi):\n  if lo >= hi: return\n  p = partition(a, lo, hi)         // pivot in final place\n  quicksort(a, lo, p - 1)\n  quicksort(a, p + 1, hi)", cs:'Sorting is the most-studied problem in computing and the standard case study in divide and conquer. Every language\u2019s sort is one of these two, tuned.', idea:'Both split the array and recurse; merge sort does the work joining, quicksort does it splitting.',
    f:[['Merge sort','Split in half, sort both, merge','O(n log n) always, O(n) extra space.'],['Quicksort','Partition around a pivot, recurse','O(n log n) expected, O(n\u00b2) worst.'],['Recurrence','T(n) = 2T(n/2) + n','log n levels of n work.'],['Lower bound','\u03a9(n log n) for comparison sorts','No comparison sort can beat it.']],
    q:[{t:'mc',q:'Why is quicksort usually faster than merge sort in practice despite a worse worst case?',o:['It makes fewer comparisons','It sorts in place with better cache locality','It is O(n) on average','It avoids recursion'],a:1,e:'Both average O(n log n) comparisons, but quicksort partitions in place with sequential memory access, while merge sort allocates and copies. On real hardware the cache behaviour dominates the constant factor.'},
       {t:'in',q:'Merge sort on 1024 items: how many levels of recursion?',a:'10',s:['Each level halves the array size.','1024 \u2192 512 \u2192 \u2026 \u2192 1, which is log\u2082(1024) halvings.','= 10 levels'],e:'Each level merges n = 1024 elements total, so about 10,240 operations.'}]},
  { id:'hashing', title:'Hash tables', code:"function get(key):\n  i = hash(key) mod m              // the modular arithmetic track\n  for (k, v) in bucket[i]:         // chaining\n    if k == key: return v\n  return MISSING                   // O(1) average, O(n) worst\n\n// resize when n / m > 0.75", cs:'The single highest-leverage data structure: it converts a linear scan into a constant-time lookup. Dictionaries, sets, caches, indexes and deduplication all run on it.', idea:'Compute a number from the key and use it as an array index, so lookup skips the search entirely.',
    f:[['Bucket index','h(key) mod m','The modular arithmetic track.'],['Load factor','\u03b1 = n / m','Resize when it exceeds ~0.75.'],['Cost','O(1) average, O(n) worst','Worst case is everything colliding.'],['Collisions','Chaining or open addressing','Two ways to share a bucket.']],
    q:[{t:'mc',q:'What makes a hash table degrade to O(n)?',o:['Too many keys','A hash function that sends many keys to the same bucket','Using strings as keys','Resizing too often'],a:1,e:'If every key lands in one bucket, the table becomes a linked list and lookup is a linear scan. This is exactly the hash-flooding attack, which is why production hash functions are randomly seeded per process.'},
       {t:'in',q:'A table has 16 buckets and 12 entries. What is the load factor as a decimal?',a:'0.75',s:['Load factor \u03b1 = n / m.','12 / 16.','= 0.75'],e:'Most implementations resize at exactly this point, doubling m to keep collisions rare.'}]},
  { id:'graph-algos', title:'BFS, DFS and Dijkstra', code:"function bfs(start):\n  queue = [start]; seen = {start}\n  while queue not empty:\n    v = queue.popFront()           // queue ⇒ shortest paths\n    for u in neighbors(v):\n      if u not in seen:\n        seen.add(u); queue.push(u) // O(V + E)\n\n// DFS: same loop, popBack() — a stack\n// Dijkstra: same loop, popCheapest() — a priority queue", cs:'Shortest routes, dependency resolution, build ordering, network reachability and social distance are all one of these three algorithms wearing a domain costume.', idea:'Traversal order is the whole algorithm: a queue gives shortest paths, a stack gives depth, a priority queue gives cheapest paths.',
    f:[['BFS','Queue \u2014 O(V + E)','Fewest edges, unweighted only.'],['DFS','Stack \u2014 O(V + E)','Cycles, topological sort, components.'],['Dijkstra','Priority queue \u2014 O((V+E) log V)','Non-negative weights.'],['Bellman-Ford','O(V\u00b7E)','Handles negative weights.']],
    q:[{t:'mc',q:'Why does Dijkstra fail with negative edge weights?',o:['It runs too slowly','It assumes a settled vertex can never be improved later','It cannot represent negative numbers','It requires a connected graph'],a:1,e:'Dijkstra finalises a vertex the moment it is popped, relying on the fact that any later path is at least as long. A negative edge can make a later path shorter, breaking that guarantee. Bellman-Ford relaxes repeatedly and survives it.'},
       {t:'in',q:'A graph has 100 vertices and 400 edges. What is V + E for BFS?',a:'500',s:['BFS touches each vertex once and each edge once.','V + E = 100 + 400.','= 500'],e:'An adjacency matrix would force 100\u00b2 = 10,000 cell reads instead.'}]},
  { id:'dp', title:'Dynamic programming', code:"memo = {}\nfunction fib(n):\n  if n <= 2: return 1              // base case\n  if n in memo: return memo[n]     // never solve twice\n  memo[n] = fib(n-1) + fib(n-2)\n  return memo[n]                   // O(2^n) → O(n)", cs:'DP turns exponential recursion into polynomial time by refusing to solve the same subproblem twice. Diffing, sequence alignment, edit distance, routing and resource allocation all rely on it.', idea:'When subproblems overlap, solve each once and store the answer.',
    f:[['Two requirements','Optimal substructure + overlapping subproblems','Both must hold.'],['Top-down','Recursion + memo table','Easiest to write.'],['Bottom-up','Fill a table in dependency order','Usually faster, no stack.'],['Cost','States \u00d7 work per state','How you price any DP.']],
    q:[{t:'mc',q:'Naive recursive Fibonacci is O(2\u207f). What does memoisation make it?',o:['O(log n)','O(n)','O(n log n)','O(n\u00b2)'],a:1,e:'There are only n distinct subproblems, and memoisation computes each exactly once at constant cost. The exponential blowup was entirely recomputation of identical calls.'},
       {t:'in',q:'A DP has 100 states and does 5 units of work per state. Total operations?',a:'500',s:['DP cost = number of states \u00d7 work per state.','100 \u00d7 5.','= 500'],e:'This product is the standard way to price any dynamic program.'}]},
  { id:'greedy', title:'Greedy algorithms', code:"function change(amount, coins):   // coins sorted descending\n  used = []\n  for c in coins:\n    while amount >= c:\n      amount -= c; used.push(c)    // best-looking choice now\n  return used\n// optimal for {1,5,10,25} — provably\n// wrong for {1,3,4} making 6 — prove before you ship", cs:'Huffman coding, Dijkstra, Kruskal and interval scheduling are greedy. When greed is provably safe it is the simplest and fastest option; when it is not, it fails silently on ordinary input.', idea:'Take the best-looking option now, and prove that doing so never rules out an optimal finish.',
    f:[['Greedy-choice property','A local optimum extends to a global one','This needs proof, not intuition.'],['Exchange argument','Swap an optimal choice for the greedy one','The standard proof technique.'],['Works','Huffman, Kruskal, interval scheduling','Provably optimal.'],['Fails','0/1 knapsack, longest path','Use DP instead.']],
    q:[{t:'mc',q:'Greedy coin change fails on coins {1, 3, 4} making 6. Why?',o:['6 is not representable','Greedy takes 4 then two 1s (3 coins); optimal is 3 + 3 (2 coins)','The coins are not sorted','It needs a larger denomination'],a:1,e:'Taking the largest coin first commits you to a worse total. This coin system lacks the greedy-choice property, so only DP finds the true optimum. Standard currency systems are designed so greedy does work.'},
       {t:'in',q:'Coins {1, 5, 10, 25}. Fewest coins to make 30?',a:'2',s:['Take the largest first: 25, leaving 5.','Take 5, leaving 0.','Two coins.'],e:'This coin set has the greedy-choice property, which is why cashiers can do it without thinking.'}]},
]},

{ id:'ai', n:'Math for AI', sub:'The mathematics a model actually runs on', lessons:[
  { id:'vectors', title:'Vectors and embeddings', graph:'vector', cs:'Every input a model sees is a vector: an image is a list of pixel values, a word is a list of learned numbers. Understanding vectors is the price of entry to machine learning.', idea:'A vector is an ordered list of numbers that names a point in a space with as many dimensions as it has entries.',
    f:[['Vector','v = [v\u2081, v\u2082, \u2026, v\u2099]','n numbers, n dimensions.'],['Addition','u + v = [u\u1d62 + v\u1d62]','Component by component.'],['Scalar multiply','cv = [cv\u1d62]','Stretches, does not rotate.'],['Magnitude','\u2016v\u2016 = \u221a(\u03a3v\u1d62\u00b2)','Pythagoras in n dimensions.'],['Unit vector','v / \u2016v\u2016','Length 1, direction only.']],
    q:[{t:'mc',q:'A word embedding has 768 dimensions. What does that mean geometrically?',o:['It stores 768 words','It is a point in 768-dimensional space','It uses 768 bytes','It has 768 possible values'],a:1,e:'Each dimension is one coordinate, so the embedding is a single point in a 768-dimensional space. Words with similar meanings end up near each other in that space, which is the entire premise of embeddings.'},
       {t:'in',q:'What is the magnitude of the vector [3, 4]?',a:'5',s:['\u2016v\u2016 = \u221a(3\u00b2 + 4\u00b2).','= \u221a(9 + 16) = \u221a25.','= 5'],e:'Pythagoras, generalised: the same formula works for 768 components.'}]},
  { id:'dotproduct', title:'Dot products and similarity', code:"function cosine(u, v):\n  dot = Σ u[i] * v[i]              // one multiply-add per dim\n  return dot / (norm(u) * norm(v)) // −1 … 1\n\n// a neural layer = thousands of dot products at once:\n// y[j] = Σ W[j][i] * x[i] + b[j]", cs:'Cosine similarity is how a search engine decides two documents are related and how a recommender finds users like you. It is one multiplication and one division away from the dot product.', idea:'The dot product measures how much two vectors point in the same direction.',
    f:[['Dot product','u \u00b7 v = \u03a3 u\u1d62v\u1d62','Multiply pairwise, sum.'],['Angle form','u \u00b7 v = \u2016u\u2016\u2016v\u2016cos \u03b8','Where the trig track pays off.'],['Cosine similarity','(u \u00b7 v) / (\u2016u\u2016\u2016v\u2016)','Ranges \u22121 to 1.'],['Orthogonal','u \u00b7 v = 0','Perpendicular, unrelated.']],
    q:[{t:'mc',q:'Two embeddings have cosine similarity 0. What does that tell you?',o:['They are identical','They are opposites','They are unrelated in direction','One of them is zero'],a:2,e:'Cosine 0 means the angle is 90 degrees, so the vectors are orthogonal and share no directional component. In an embedding space this is the signature of unrelated meanings; \u22121 would mean opposite.'},
       {t:'in',q:'Compute the dot product of [2, 3] and [4, 1].',a:'11',s:['Multiply matching components: 2\u00d74 = 8 and 3\u00d71 = 3.','Sum them: 8 + 3.','= 11'],e:'A neural network layer is thousands of these running in parallel.'}]},
  { id:'matrices', title:'Matrices and transformations', cs:'A neural network layer is a matrix multiply plus a bias. GPUs exist largely to do this one operation fast, and the shape rules decide whether your model compiles at all.', idea:'A matrix is a function that takes a vector and returns another vector.',
    f:[['Shape rule','(m\u00d7n)(n\u00d7p) = (m\u00d7p)','Inner dimensions must match.'],['Entry','c\u1d62\u2c7c = row i \u00b7 column j','A dot product each.'],['Not commutative','AB \u2260 BA','Order changes the result.'],['Identity','IA = A','The do-nothing matrix.'],['Layer','y = Wx + b','One line of a neural net.']],
    q:[{t:'mc',q:'You multiply a 4\u00d73 matrix by a 3\u00d75 matrix. What is the result shape?',o:['4\u00d75','3\u00d73','5\u00d74','Undefined'],a:0,e:'The inner dimensions (3 and 3) match, so the product is legal and takes the outer dimensions: 4\u00d75. Mismatched inner dimensions are the single most common error in model code.'},
       {t:'in',q:'A layer maps 512 inputs to 256 outputs. How many weights are in W?',a:'131072',s:['W has one weight per input-output pair.','512 \u00d7 256.','= 131,072 weights, plus 256 bias terms.'],e:'Multiply that by dozens of layers and you see where billions of parameters come from.'}]},
  { id:'gradient-descent', title:'Gradient descent', graph:'descent', code:"for step in 1..N:\n  g = gradient(loss, θ)            // chain rule, backwards\n  θ = θ - η * g                    // the minus sign IS descent\n  if norm(g) < ε: break            // flat ⇒ converged\n\n// η too big → loss oscillates; too small → crawls", cs:'This is how essentially every model is trained. The chain rule computes the gradient, and this loop walks the parameters downhill until the error stops falling.', idea:'Repeatedly step every parameter in the direction that most reduces the error.',
    f:[['Update rule','\u03b8 \u2190 \u03b8 \u2212 \u03b7\u2207L','\u03b7 is the learning rate.'],['Gradient','\u2207L = vector of partial derivatives','Direction of steepest ascent.'],['Minus sign','Descend, not ascend','Downhill is the negative.'],['Learning rate','Too big diverges, too small crawls','The key hyperparameter.'],['Convergence','\u2207L \u2248 0','Flat means done.']],
    q:[{t:'mc',q:'Training loss oscillates wildly and never settles. What is the most likely cause?',o:['Learning rate too high','Learning rate too low','Not enough data','Too many layers'],a:0,e:'An oversized step overshoots the minimum and lands further up the other side, repeatedly. The loss bounces rather than descends. Too low a rate produces the opposite symptom: smooth but painfully slow progress.'},
       {t:'in',q:'Parameter \u03b8 = 10, gradient = 4, learning rate = 0.5. What is \u03b8 after one step?',a:'8',s:['Update: \u03b8 \u2190 \u03b8 \u2212 \u03b7\u2207L.','10 \u2212 0.5 \u00d7 4 = 10 \u2212 2.','= 8'],e:'The minus sign is what makes it descent; dropping it climbs the loss surface instead.'}]},
  { id:'bayes', title:'Probability and Bayes\u2019 theorem', code:"function posterior(pBgivenA, pA, pB):\n  return pBgivenA * pA / pB        // Bayes, one line\n\n// spam filter: P(spam | word) from\n// P(word | spam), P(spam), P(word)", cs:'Spam filters, medical triage models and every calibrated classifier reason with Bayes. It is also the formal reason a highly accurate test can still be usually wrong on a rare condition.', idea:'Bayes updates a prior belief with new evidence to produce a posterior belief.',
    f:[['Bayes','P(A|B) = P(B|A)P(A) / P(B)','Reverse the conditional.'],['Prior','P(A)','Belief before evidence.'],['Posterior','P(A|B)','Belief after evidence.'],['Base rate','Rarity of A','Ignoring it is the classic error.'],['Naive Bayes','Assume features independent','Wrong but useful.']],
    q:[{t:'mc',q:'A disease affects 1 in 1000. A test is 99% accurate. You test positive. Roughly what is the chance you have it?',o:['99%','90%','50%','9%'],a:3,e:'In 1000 people, 1 is sick and tests positive, while about 10 of the 999 healthy people test positive falsely. So roughly 1 in 11 positives is real, about 9%. The base rate dominates, which is why rare-event classifiers need precision, not accuracy.'},
       {t:'in',q:'P(B|A) = 0.8, P(A) = 0.5, P(B) = 0.4. What is P(A|B)?',a:'1',s:['Bayes: P(A|B) = P(B|A)P(A)/P(B).','= (0.8 \u00d7 0.5)/0.4 = 0.4/0.4.','= 1'],e:'A posterior of 1 means B occurs only when A does \u2014 the evidence is conclusive.'}]},
  { id:'entropy', title:'Entropy and cross-entropy loss', graph:'entropy', cs:'Cross-entropy is the loss function behind nearly every classifier ever trained. Entropy is also the theoretical floor on compression, so it decides how small a ZIP file can possibly be.', idea:'Entropy measures surprise: how many bits it takes on average to record which outcome occurred.',
    f:[['Entropy','H = \u2212\u03a3 p\u1d62 log\u2082 p\u1d62','Average bits of surprise.'],['Certainty','p = 1 \u21d2 H = 0','No surprise, no bits.'],['Maximum','Uniform over n \u21d2 H = log\u2082 n','Least predictable.'],['Cross-entropy','\u2212\u03a3 y\u1d62 log(\u0177\u1d62)','The classifier loss.'],['Confident and wrong','log(small) \u2192 huge penalty','Why calibration matters.']],
    q:[{t:'mc',q:'Why does cross-entropy punish a confident wrong prediction so heavily?',o:['It squares the error','It takes the log of a near-zero probability, which is a large negative number','It counts wrong answers twice','It normalises across classes'],a:1,e:'Loss is \u2212log(\u0177) for the true class. If the model assigned 0.001 to the correct answer, \u2212log(0.001) is about 6.9, while a mild error near 0.5 costs only 0.69. Confidence in a wrong answer is penalised roughly ten times harder.'},
       {t:'in',q:'What is the entropy in bits of a fair coin flip?',a:'1',s:['Two outcomes, each with p = 0.5.','H = \u2212(0.5 log\u2082 0.5 + 0.5 log\u2082 0.5) = \u2212(\u22120.5 \u2212 0.5).','= 1 bit'],e:'One bit is exactly what it takes to record heads or tails \u2014 entropy and storage are the same quantity.'}]},
]},
];


// Recurring ideas that run across tracks. Each entry: the move, what it buys, and where it reappears.
export const THREADS = [
  { id:'halving', n:'Halving', line:'Cut the problem in two and the cost becomes a count of cuts, not a count of items.',
    why:'The single most valuable move in computing. It converts linear work into logarithmic work, and it is why a million-item lookup takes twenty comparisons rather than a million.',
    steps:[['exponents','2\u207f counts doublings'],['logarithms','the inverse: how many halvings'],['binary-search','halve the search range'],['recurrences','T(n)=T(n/2)+1'],['sorting','halve, sort, merge'],['trees','balanced height is log n'],['rsa','square-and-multiply halves the exponent']] },
  { id:'counting', n:'Counting the space',line:'Size the set of possibilities before you search it.',
    why:'Whether a problem is trivial or impossible is usually decided by one multiplication. 10\u2074 PINs fall in a millisecond; 2\u2075\u2070 subsets outlast the sun.',
    steps:[['counting','multiply independent choices'],['permutations','order matters, or not'],['sets','2\u207f subsets'],['binomial','C(n,k) as a coefficient'],['probability','favourable over total'],['advanced-counting','pigeonhole forces collisions'],['pnp','when the space is too big to search']] },
  { id:'rates', n:'Rates of change', line:'Ask not where a thing is, but how fast it is moving right now.',
    why:'Every optimisation, every training loop and every performance curve is read through this lens: slope says direction, curvature says whether it is levelling off.',
    steps:[['linear','constant rate: slope'],['limits','shrink the interval to a point'],['derivatives','the instantaneous rate'],['chain-rule','rates multiply through a chain'],['optimization','flat slope marks the optimum'],['curve-sketching','second derivative reads the bend'],['gradient-descent','step against the gradient']] },
  { id:'accumulate', n:'Accumulation', line:'Slice something awkward into simple pieces, price each piece, sum.',
    why:'The same recipe prices an odd-shaped field, a total from a rate, an expected value over a continuous range, and the amortised cost of a data structure.',
    steps:[['sequences','sums with closed forms'],['integrals','sum of infinitely thin slices'],['applications','areas, volumes, averages'],['series','infinite sums that still settle'],['improper','unbounded range, finite total'],['amortized','spread a rare cost over many cheap ones'],['expected-value','weight each outcome by its probability']] },
  { id:'wrap', n:'Wrapping around', line:'Keep only the remainder and the number line becomes a circle.',
    why:'Hash buckets, circular buffers, integer overflow and public-key cryptography are all one operation \u2014 the one nobody formally taught you.',
    steps:[['factors','divisibility and remainders'],['modular','arithmetic on a clock face'],['gcd','Euclid reduces by remainder'],['mod-inverse','the antidote to multiplication'],['fermat-euler','powers cycle back to 1'],['rsa','encryption and decryption as inverse rides'],['hashing','hash mod m picks a bucket']] },
  { id:'structure', n:'Structure beats brute force', line:'A shortcut is never cleverness with code; it is a property of the problem.',
    why:'Sortedness admits binary search. Overlap admits memoisation. A safe local choice admits greed. Recognising the property is the whole job \u2014 the paradigm is just its name.',
    steps:[['develop','find the property, then the paradigm'],['binary-search','sortedness'],['dp','overlapping subproblems'],['greedy','provably safe local choices'],['dags','acyclicity gives an order'],['bipartite','two sides give a matching'],['pnp','when no property exists']] },
  { id:'proof', n:'Proof as engineering', line:'An argument that covers infinitely many cases at once, which no test suite can.',
    why:'Loop invariants are induction. Correctness of a recursive function is induction. Testing shows the presence of bugs, never their absence \u2014 which is why the last step of algorithm design is an argument, not a green build.',
    steps:[['logic','connectives and implication'],['quantifiers','for-all versus there-exists'],['proofs','direct, contrapositive, contradiction'],['induction','base case plus the domino step'],['recurrence','unroll, guess, prove'],['develop','prove before you optimise']] },
  { id:'linearalgebra', n:'Everything becomes a vector', line:'Turn any object into a list of numbers and one set of mathematics handles all of it.',
    why:'An image, a word, a user and a document are incomparable until they are vectors. Then similarity is an angle, a model layer is a matrix, and the whole field opens.',
    steps:[['coordinates','a point as an ordered pair'],['right-triangles','length from components'],['vectors','n components, n dimensions'],['dotproduct','similarity as an angle'],['matrices','a layer is a matrix multiply'],['gradient-descent','train the matrix entries']] },
];

export const TOTAL_LESSONS = TRACKS.reduce((n, t) => n + t.lessons.length, 0);
